programs.sol:
"""Recognize document-opening syntax, with small lexical/context corrections.

Very large positives mark an opening empty // comment, an HTML declaration,
or a long prefix dominated by carriage returns.  Headings, escaped
whitespace, and code declarations tend negative.  Initial Latin words have
case/spacing-dependent offsets.  Away from the start most tokens are near zero;
chat markers, locative words, and programming/probability phrases differ.
The 12 and {[ opening prefixes are explicit, narrow exceptions.
"""
import re

READS = ()
CODE_DECLARATIONS = {
    'package', 'namespace', 'def', 'public', 'class',
    'import', 'using', 'from', 'function',
}
LOCATIVES = {' en', ' em', ' в', ' В'}  # Romance and Russian "in"


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', 0, '')
    _, position, line, return_run, first = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    value = -0.0006

    return_run = return_run + 1 if token == '\r' else 0
    if token == '\r':
        before_run = position + 1 - return_run
        if before_run == 0:
            value = 7.587
        elif return_run >= 32:
            # A long uninterrupted run must dominate the preceding text.
            excess = max(0.0, return_run - 1.5 * before_run)
            value = 7.587 * excess / (return_run + 3 * before_run)
    elif token == '<|im_start|>':
        value = -0.228 if position == 0 else -0.063
    elif token == '<|endoftext|>':
        value = -1.778 if position == 0 else -0.018
    elif position == 0:
        first = token
        if token == '//\n':
            value = 8.318
        elif token == '<!':
            value = 9.252
        elif token == '//':
            value = 0.755
        elif token == '<!--':
            value = 1.247
        elif token in {'#', '##'}:
            value = -0.594 if token == '#' else -1.346
        elif token in {r'\n', r'\t'}:
            value = -1.2
        elif token in CODE_DECLARATIONS:
            value = -0.82
        elif word.isascii() and word.isdecimal():
            value = 0.126
        elif word.isascii() and word.isalpha():
            spaced = token[0].isspace()
            if word.lower() in {'a', 'an'}:
                value = -0.215 if spaced else -0.55
            elif word.lower() == 'the':
                value = 0.033 if spaced else -0.225
            elif word.istitle() and len(word) > 1:
                value = -0.18 if spaced else -0.31
            elif word.islower():
                value = -0.062 if spaced else -0.03
    elif position == 1 and first == '1' and token == '2':
        # The decimal prefix 12 has a distinct opening response.
        value = 1.963
    elif position == 1 and first == '{' and token == '[':
        # Mixed brace/bracket template opener.
        value = 2.467
    elif token in LOCATIVES:
        value = -0.125
    elif token == ' from' and line.endswith('picked without replacement'):
        value = -1.12
    elif token == ' in' and re.fullmatch(r'\s*(?:async )?for [\w, ]+', line):
        value = -0.23
    elif word == 'from' and not line.strip():
        value = -0.13
    elif word == 'import':
        value = 0.11 if token.startswith(' ') else 0.052
    elif token == '<|im_end|>':
        value = 0.026
    elif token == '<tool_call>':
        value = 0.073
    elif token == '</tool_call>':
        value = -0.046
    elif token == '··':
        value = -0.172

    line = (line + token).split('\n')[-1][-160:]
    return (doc, position + 1, line, return_run, first), value

programs.haiku:
"""layers.1.mlp.down_proj:4865: a document-opening feature.

The component is near zero in the middle of ordinary text. It responds to two things:

1. The first token of a document (the token right after <|endoftext|>, or the first token
   of a row). The value depends on that token:
   - a few openers give a large spike: a "//" comment line ("//\\n"), "<!" markup, and a
     carriage return "\\r";
   - code keywords and file-start markers ("package", "import", "def", "#", "##", ...)
     give a moderately negative value;
   - capitalised words give a mild negative value, digits a mild positive one;
   - anything else gives 0.
2. Runs of carriage returns ("\\r\\r\\r..."). A run that opens a document stays at the
   opener's large value (7.6) for its whole length. A run started mid-document stays near
   zero, then builds up slowly as the run gets long (about 1 after some 60 returns).

The program tracks document starts from `document_ids` and the length of the current
carriage-return run in its carry.
"""

READS = ()

# Rare, very strong openers.
SPIKES = {"//\n": 8.3, "<!": 9.2, "\r": 7.6}

# Code keywords and markers that open a source file.
CODE_OPENERS = {
    "package", "import", "using", "def", "namespace", "use", "from",
    "#", "##", "#!/", "#ifndef", "#include", "\\n", "\\t",
}


def opener_value(token):
    if token in SPIKES:
        return SPIKES[token]
    if token in CODE_OPENERS:
        return -0.6
    if token[:1].isupper():
        return -0.2
    if token[:1].isdigit():
        return 0.1
    return 0.0


def run_value(run_length, opens_document):
    # A carriage-return run that opens a document keeps the opener's spike.
    if opens_document:
        return SPIKES["\r"]
    # A mid-document run builds up slowly once it is long.
    return min(1.0, max(0.0, (run_length - 12) / 50.0))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if token == "\r":
        # The carry is set only when the previous token was a carriage return.
        if carry is not None and not new_doc:
            run_length, opens = carry[0] + 1, carry[1]
        else:
            run_length, opens = 1, new_doc
        return (run_length, opens), float(run_value(run_length, opens))
    if new_doc:
        return None, float(opener_value(token))
    return None, 0.0

programs.sol:
"""A detector for source-file endings and shared programming infrastructure.

Negative responses mark file suffixes, utility namespaces, common definitions,
constants, and helper code. Imports of custom utility modules are particularly
strong; java.util is an important exception. Spelling boundaries distinguish a
namespace, a path segment, a compound identifier, and an ordinary prose word.
Carriage returns at an otherwise empty document start are also negative.
Macro definitions and scope-qualified const have small positive rules.
"""
import re

READS = ()

EXTENSIONS = {
    'py': -1.48, 'rs': -1.9, 'go': -1.5, 'js': -1.3,
    'ts': -1.3, 'java': -.7, 'c': -.4, 'h': -.65,
    'cpp': -1.3, 'hpp': -1.2, 'cs': -1.3, 'rb': -1.2,
    'php': -.9, 'sh': -1.3, 'vue': -.9, 'html': -.6,
    'yml': -1.2, 'yaml': -.9, 'json': -.9, 'xml': -.6,
    'mod': -1.7, 'sum': -.65, 'jar': -1.15, 'zip': -1.5,
    'md': -.8, 'txt': -1.0, 'pdf': -.7, 'csv': -.8,
    'png': -.55, 'gif': -1.0, 'tar': -1.0,
}
INFRASTRUCTURE = {
    'core': -.6, 'base': -.7, 'model': -.55, 'models': -.8,
    'entity': -.6, 'repository': -.7, 'handler': -.8,
    'exception': -1.6, 'exceptions': -1.6, 'config': -1.1,
    'settings': -.7, 'logging': -1.0, 'logger': -.8,
    'helper': -1.3, 'helpers': -1.5, 'types': -1.3,
}
IMPORT = re.compile(
    r'^\s*(?:\d+[:\t ]+)?[+-]?\s*'
    r'(?:import|from|package|use|#\s*include)\b'
    r'|\b(?:require|import)\s*\('
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent, blank_start = '', '', True
    else:
        _, previous, recent, blank_start = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    name = s.lstrip('./_-')
    low = name.lower()
    importing = bool(IMPORT.search(recent))
    path_start = previous.endswith('/') or (
        importing and previous.endswith(("'", '"', '<'))
    )
    value = 0.0

    if s.startswith('.') and s[1:] in EXTENSIONS:
        value = EXTENSIONS[s[1:]]
        if s == '.java':
            in_stack_frame = re.search(r'\([\w$]+$', recent)
            value = .4 if in_stack_frame else -1.05
        if s == '.c' and ('/' in recent.split(' ')[-1]
                          or previous.strip() == 'main'):
            value = -1.5
        if previous.strip() in ('self', 'this'):
            value = 0.0
    elif previous.endswith('.') and s in EXTENSIONS:
        value = EXTENSIONS[s] * 1.5

    if low in ('util', 'utils', 'utility', 'utilities'):
        if s.startswith('.'):
            value = -4.6 if low != 'util' else -4.8
            if name == 'Utils':
                value = -5.8
            if previous.strip() == 'java':
                value = 0.0
        elif s.startswith(('/', '_', '-')):
            value = -1.3 if low == 'utils' else -1.9
        elif previous.strip() == 'from':
            value = -5.6
        elif name[0].isupper():
            value = -2.3 if s == token else -1.0
        elif path_start:
            value = -3.5
        else:
            value = -1.2
        if (name in ('utility', 'utilities')
                and token[0].isspace() and not importing):
            value = .1
    elif low == 'common':
        if s.startswith('.'):
            value = -5.5 if importing else -2.0
            if 'org.apache.' in recent:
                value = -.5
        elif s.startswith(('/', '_', '-')):
            value = -1.7
        elif importing or path_start:
            value = -4.5
    elif low in ('constants', 'consts'):
        value = -3.0
        if path_start or s.startswith('.'):
            value = -4.5
        if token.startswith(' ') and not importing:
            value = 0.0
    elif low == 'constant':
        shared = previous.lower().endswith(('common', 'global'))
        value = -5.3 if shared else -.4
        if s.startswith('.'):
            value = -4.5
        if token.startswith(' ') and not importing:
            value = 0.0
    elif s.startswith('.') and low in INFRASTRUCTURE:
        value = INFRASTRUCTURE[low]
    elif low in ('tools', 'helpers', 'definitions', 'types', 'functions'):
        if path_start:
            value = -3.0
        elif s.startswith(('/', '_', '-')):
            value = -1.0
        elif token == s:
            value = -3.0 if importing else -.7
        if previous.lower().endswith(('common', 'global')):
            value = -6.0
    elif low in ('helper', 'logger', 'logging', 'exception'):
        value = -.7
    elif low == 'global':
        value = -.9 if s == token or previous.isspace() else .1

    if s == 'import':
        value = -.2 if token == s else -.4
        if previous.strip().lstrip('.') in ('utils', 'util', 'common'):
            value = -2.7
    if token == '#define':
        value = 1.0
    if s == 'const' and previous.endswith('::'):
        value = 1.4

    blank_start = blank_start and token == '\r'
    if token == '\r':
        value = -3.7 if blank_start else -.08
    recent = (recent + token).replace('\\n', '\n')[-120:]
    recent = recent.rsplit('\n', 1)[-1]
    return (doc, token, recent, blank_start), value

programs.haiku:
"""Program v7: file extensions and project-module names (common, utils, config, ...) push the
component negative. The push is strongest for module names inside a Java-style package path
("com.acme.common") or a Python "from config import", and weaker on ordinary prose words."""
READS = ()

FILE_EXTENSIONS = set(
    ".py .go .ts .rs .js .md .json .java .php .sh .yml .yaml .txt .cfg .h .c .cpp .cc .so .ini "
    ".css .vue .lua .jar .zip .gif .conf .lib .inc .def .mod .exe .html .xml .toml .sql .csv .png "
    ".jpg .scss .kt .swift .rb .pl .cs .hpp .tsx .jsx .dll .spec .pdf".split()
)
# generic names of project-internal modules, folders and packages
MODULE_NAMES = set(
    "common util utils helpers helper constants config definitions shared utilities utility "
    "Common Util Utils Helper Helpers Constants Config Utility Utilities types".split()
)
JAVA_PACKAGES = {"java", "javax", "org", "android", "io", "net", "sun", "jdk"}
PATH_WORDS = {"src", "pkg", "lib", "app", "packages"}


def recent(prefix, count):
    """Up to `count` tokens just before the current one, in the same document, newest first."""
    strings = prefix.token_strings
    out = []
    for i in range(len(strings) - 2, max(-1, len(strings) - 2 - count), -1):
        if prefix.document_ids[i] != prefix.document_ids[-1]:
            break
        out.append(strings[i].strip())
    return out


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    name = token.strip("./_ ")
    context = recent(prefix, 8)
    before = context[0] if context else ""
    if word in FILE_EXTENSIONS:
        if any("/" in s for s in context):
            return carry, -1.4  # inside a file path, as in "src/main.go"
        if any("import" in s or "include" in s for s in context):
            return carry, -0.7  # inside an import or include line
        return carry, -0.9
    if name not in MODULE_NAMES:
        return carry, 0.0
    if token.startswith(" "):
        if before == "from":
            return carry, -3.5  # "from config import ..."
        if before in ("import", "using"):
            return carry, -1.5
        return carry, 0.0  # " common" in ordinary prose
    if before in JAVA_PACKAGES:
        return carry, 0.0  # java.util is the standard library, not a project module
    if any(s in ("com", "org") for s in context):
        return carry, -3.0  # "import com.acme.common.Foo"
    if any("/" in s or s in PATH_WORDS for s in context):
        return carry, -1.6  # a folder name, as in "/src/utils"
    return carry, -1.0

programs.sol:
"""A multilingual 'as / like / how' word detector.

Different languages have very different response sizes.  Words assembled
from several tokens count at their final piece too.  Italian 'come' and
Scandinavian 'som' need a language check, since they also occur in English.
Recent word frequencies disambiguate these and a few other words; chat
labels are ignored. 'Come' without preceding prose gets a separate default.
Familiar
phrases such as 'such as' and 'would like' adjust the English responses.
Greek preposition prefixes and Chinese comparison characters count too.
Danish 'mere' (more) has a negative response. Everything unlisted is zero;
small residual fluctuations and many incidental word fragments are omitted.
"""
import re
from wordfreq import zipf_frequency

READS = ()

# Comparison / manner words, grouped by language rather than token ID.
MANNER = {
    'like': 0.37, 'than': 0.29,
    'comme': 9.3,
    'como': 6.7, 'cómo': 5.5,
    'als': 4.5, 'wie': 2.4,
    'като': 8.5,
    'jako': 5.4, 'jak': 2.8, 'ako': 5.0,
    'kaip': 8.5, 'cum': 3.0, 'kako': 8.5, 'siccome': 6.5,
    # Greek 'according to', including unfinished token pieces.
    'κατ': 6.3, 'καθ': 3.8,
    'ك': 2.5, 'كما': 3.2,
    'như': 1.0,
}
WORD = re.compile(r'[^\W\d_]+\Z', re.UNICODE)
WORDS = re.compile(r'[^\W\d_]+', re.UNICODE)
CHAT_LABELS = {'user', 'assistant', 'system', 'im', 'start', 'end', 'endoftext'}


def language_margin(text, language):
    words = [w for w in WORDS.findall(text.lower())
             if w not in CHAT_LABELS][-30:]
    if not words:
        return 0.0
    # Compare recent words' familiarity in this language versus English.
    evidence = [
        max(-3.0, min(3.0, zipf_frequency(w, language)
                       - zipf_frequency(w, 'en')))
        for w in words if len(w) > 1
    ]
    return sum(evidence) / max(1, len(evidence))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else b''
    newest = prefix.token_bytes[-1]
    if newest in {b'<|endoftext|>', b'<|im_start|>', b'<|im_end|>'}:
        recent = b''
    text = (recent + newest)[-600:].decode('utf-8', errors='replace')
    match = WORD.search(text)
    value = 0.0
    if match and newest:
        word = match.group().lower()
        value = MANNER.get(word, 0.0)
        before = text[:match.start()]
        previous = WORDS.findall(before.lower())[-1:]
        previous = previous[0] if previous else ''
        if word == 'come':
            italian = language_margin(before, 'it')
            value = 10.0 if italian > 0.2 else -0.45
            if match.group()[0].isupper():
                value = 11.5 if italian > 0.2 else 0.5
            prior_words = [w for w in WORDS.findall(before.lower())
                           if w not in CHAT_LABELS]
            if not prior_words:
                value = 7.0 if match.group()[0].isupper() else 5.5
        elif word == 'som':
            scores = {lang: language_margin(before, lang)
                      for lang in ('sv', 'da', 'nb', 'de', 'it', 'pt', 'fr')}
            lang = max(scores, key=scores.get)
            if lang in ('sv', 'da', 'nb') and scores[lang] > 0.2:
                value = 5.6
        elif word == 'comme' and match.group()[0].isupper():
            value = 14.0
        elif word == 'como' and not newest.startswith(b' '):
            value = 8.5
        elif word == 'wie' and match.group()[0].isupper():
            value = 3.2
        elif word in {'как', 'як'}:
            value = 5.8 if match.group()[0].isupper() else 4.1
            if previous in {'так', 'такие', 'таких'}:
                value = 1.8
        elif word == 'als' and match.group().isupper():
            value = 0.0
        elif word == 'als' and match.group()[0].isupper():
            value = 5.2
        elif word == 'as':
            value = 0.59 if match.group()[0].isupper() else 0.72
            value = {'such': 0.30, 'long': 0.08, 'soon': 0.29,
                     'same': 0.94, 'not': 1.14, 'well': 0.81}.get(previous, value)
        elif word == 'like':
            value = {'would': -0.20, 'just': 0.67, 'is': 0.68,
                     'feel': 0.53}.get(previous, value)
        elif word == 'comment':
            value = 4.8 if language_margin(before, 'fr') > 0.2 else -0.25
        elif word == 'ca' and language_margin(before, 'ro') > 0.3:
            value = 7.8
        elif word == 'cum' and language_margin(before, 'ro') > 0.3:
            value = 7.5
        elif word == 'mere' and language_margin(before, 'da') > 0.3:
            value = -5.5
        if (word == 'wie' and language_margin(before, 'pl')
                > language_margin(before, 'de')):
            value = -2.0
    # Chinese comparison characters do not need a word boundary.
    token = newest.decode('utf-8', errors='replace').strip()
    if token in {'像', '就像', '如同'}:
        value = 0.49
    elif token == '如':
        value = 0.33
    elif token == '似':
        value = 0.67
    return (doc, (recent + newest)[-600:]), float(value)

"""A small English noun-phrase approximation.

Predicative descriptions ("is the only/first") are positive. Possessive
phrases have signed lexical responses: names, attention and turns positive;
individualizing modifiers and parent/friend relations negative. Numeric
ordinals and a few longer possessive phrases have separate rules.

The program retains six nonempty tokens, resetting at document boundaries.
It deliberately leaves most words near zero; it is not a full noun parser.
"""
from functools import lru_cache
import inflect
import wordnet

READS = ()
POSSESSIVES = frozenset("my your his her its our their thy 's ’s".split())
COPULAS = frozenset(
    'is am are was were be been being become becomes became remain remains '
    'remained'.split()
)
SUBJECTS = frozenset(
    'it he she that there here what who how where when'.split()
)
CLITICS = frozenset(("'s", '’s', "'re", '’re', "'m", '’m'))
ADVERBS = frozenset(
    'not never also still currently probably perhaps certainly now already '
    'even just virtually almost really actually arguably by far'.split()
)
_numbers = inflect.engine()
ORDINALS = frozenset(
    _numbers.number_to_words(_numbers.ordinal(n)) for n in range(1, 21)
)
LAST = frozenset(('last', 'latest', 'final'))


def after_copula(words):
    for i in range(len(words) - 1, -1, -1):
        w = words[i]
        if w in COPULAS:
            return True
        if (w in CLITICS and i > 0
                and words[i-1] in SUBJECTS | {'i', 'you', 'we', 'they'}):
            return True
        if w not in ADVERBS:
            break
    return False


@lru_cache(maxsize=8000)
def superlative(word):
    return (word.endswith('est') or word in {'most', 'least'}) and (
        'adjective' in wordnet.parts_of_speech(word)
    )


@lru_cache(maxsize=8000)
def possessive_word(word):
    if not word.isascii() or not word.isalpha():
        return 0.0
    if word in {'personal', 'individual', 'respective'}:
        return -2.63
    if word in {'local', 'native', 'hometown'}:
        return -1.72
    if word in {'favorite', 'favourite'}:
        return -0.98
    if word in {'name', 'names'}:
        return 1.64
    if word == 'attention':
        return 2.51
    if word == 'turn':
        return 3.26
    if word == 'fault':
        return 4.40
    if word == 'knowledge':
        return 1.69
    if word == 'office':
        return 2.03
    value = 0.0
    if word in ORDINALS or word.endswith('teenth'):
        value += 1.13
    if word in LAST:
        value += 0.72
    if word in {'one', 'ones'}:
        value -= 2.03
    if wordnet.is_a(word, 'parent'):
        value -= 0.85
    if wordnet.is_a(word, 'friend'):
        value -= 0.68
    if word == 'fellow':
        value -= 1.56
    if superlative(word):
        value -= 0.62
    if word in {'closest', 'nearest'}:
        value -= 1.56
    return value


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    h = carry[1] if carry is not None and carry[0] == doc else ()
    w = prefix.token_strings[-1].strip().lower()
    p = h[-1] if h else ''
    pp = h[-2] if len(h) > 1 else ''
    predicate = after_copula(h[:-1])
    possessive = p in POSSESSIVES and not (
        p in {"'s", '’s'} and pp in SUBJECTS
    )
    value = 0.0013
    if possessive:
        value += possessive_word(w)
        if w == 'knowledge' and h[-3:-1] == ('best', 'of'):
            value += 3.32
    elif p == 'the':
        selection = pp == 'of' and len(h) > 2 and h[-3] in {'one', 'some'}
        if w == 'only':
            value += 1.59 + 4.14 * predicate
        if w in ORDINALS or w.endswith('teenth'):
            value += 1.67 * predicate + 1.18 * selection
        if w == 'first':
            value += 1.62 * predicate
        if w in LAST:
            value += 2.04 * predicate
        if w in {'one', 'ones'}:
            value += 1.61 * predicate
        if superlative(w):
            value += 0.61 * predicate + 0.44 * selection
    if w == 'time' and p == 'first':
        if pp in POSSESSIVES:
            value += 5.38
        elif pp == 'the' and len(h) > 2 and h[-3] in COPULAS:
            value += 4.21
    if w in {'st', 'nd', 'rd', 'th'} and p.isdigit():
        value += 0.55
        i = len(h) - 1
        while i >= 0 and h[i].isdigit():
            i -= 1
        if i >= 0 and h[i] in POSSESSIVES:
            value += 2.34
    if w in {'his', 'her'} and p == 'or' and pp in {'his', 'her'}:
        value -= 1.94
    if w:
        h = (h + (w,))[-6:]
    return (doc, h), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:4868: a predicate-ordinal and possessive-noun detector.

The component is near zero on almost every token. It fires on the word that follows a
short function word, in two kinds of context:

1. "The only" and predicate superlatives. "the only" gives a strong positive value
   ("the only one", "is the only"). After a copula ("is", "was", "be", "became",
   "'re", "not") plus "the", the ordinal "first", "second", "third", "last" ("is the
   first study", "was the last") is strongly positive, and "best", "most", "largest"
   weakly so. The same ordinals after other words ("of the first", "in the last")
   stay near zero, so the copula is what matters. "first time" makes "time" positive.

2. The word after a possessive ("his", "her", "my", "your", "their", "our", "its", or
   's). A modifier or a relational person-noun ("their respective", "your personal",
   "our local", "my mother", "his best") pushes the component negative, since a noun
   has to follow. A head noun that completes the phrase ("his attention", "my name",
   "his office", "their team", "my first") pushes it positive.

Everything else predicts 0. The word lists are hand-picked from the component's
strongest cases in training text. They are a sketch of the pattern, not a full
lexicon, so they capture only part of the variance.
"""

READS = ()

POSSESSIVE = {"his", "her", "my", "your", "their", "our", "its", "'s", "’s"}

# Words that come before a predicate noun phrase ("X is the first ...").
COPULA = {"is", "was", "be", "are", "were", "became", "become", "'re", "’re", "'s", "’s", "not"}

# Modifiers that come before a noun and restrict it (adjectives, determiner-like words).
MODIFIER = {
    "respective", "individual", "personal", "local", "native", "fellow", "former",
    "senior", "special", "specific", "unique", "private", "proper", "mental", "human",
    "professional", "favorite", "best", "old", "two", "one",
}

# Person nouns that are typically the possessed relation ("my mother", "their parents").
PEOPLE = {
    "mother", "father", "parents", "parent", "friends", "friend", "client", "customer",
    "user", "owner", "teacher", "contact", "target",
}

# Head nouns that complete the phrase after a possessive.
THING = {
    "attention", "knowledge", "name", "office", "kind", "credit", "mind", "business",
    "team", "car", "group", "place", "world", "style", "information", "desk", "mistake",
    "fault", "department", "organization", "kingdom", "party", "lap", "jurisdiction",
    "first", "turn",
}

ORDINAL = {"first", "second", "third", "fourth", "fifth", "sixth", "seventh", "eighth", "last"}

# Superlatives that are weaker in the same predicate position.
SUPERLATIVE = {"best", "most", "largest", "biggest", "next"}


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.document_ids[t - 1] != prefix.document_ids[t]:
        return None, 0.0
    # The last three tokens (fewer at the start of a document): w2, prev, cur.
    words = [s.strip().lower() for s in prefix.token_strings[max(0, t - 2) : t + 1]]
    cur = words[-1]
    prev = words[-2] if len(words) >= 2 else ""
    if prev in POSSESSIVE:
        if cur in MODIFIER or cur in PEOPLE:
            return None, -1.5
        if cur in THING:
            return None, 1.2
        return None, 0.0
    if prev == "first" and cur == "time":
        return None, 1.5
    if prev == "the":
        if cur == "only":
            return None, 4.0 if len(words) == 3 and words[0] in COPULA else 3.0
        if len(words) == 3 and words[0] in COPULA:
            if cur in ORDINAL:
                return None, 3.0
            if cur in SUPERLATIVE:
                return None, 1.0
    return None, 0.0

