"""Approximate a sparse response to repeated written U-like vowels.

Look for successive U occurrences separated by one to five letters, especially
across short word fragments. Familiar English/Russian prefixes weaken the cue;
a fading trace extends it onto following letters. This is a spelling heuristic,
not a general pronunciation model. Document-initial U spellings receive a small
extra response; middle-dot-only tokens have a separate positive response.
"""
import unicodedata
from functools import lru_cache
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=65536)
def vowel_positions(token):
    text = unicodedata.normalize('NFD', token.lower())
    letters = ''.join(c for c in text if c.isalpha() or c in 'ุู')
    points = []
    for i, char in enumerate(letters):
        if char in 'ุู':  # Thai short/long u vowel marks.
            weight = 1.
        elif regex.match(r'[\p{Latin}\p{Cyrillic}\p{Hiragana}\p{Katakana}]', char):
            weight = float('u' in anyascii(char))
        else:
            weight = 0.
        if char == 'ю':
            weight *= .5
        if i and letters[i-1] in 'gq' and char == 'u':
            weight *= .35
        if regex.match(r'[\p{Hiragana}\p{Katakana}]', char):
            weight *= .25
        if weight:
            points.append((i, weight))
    return points, max(1, len(letters))


@lru_cache(maxsize=32768)
def unfamiliarity(word):
    language = 'ru' if regex.search(r'\p{Cyrillic}', word) else 'en'
    frequency = zipf_frequency(word, language)
    return min(1., max(0., (5. - frequency) / 1.5))


def pair_across(previous, current, offset):
    if not previous or not current:
        return 0.
    i, a = previous[-1]
    j, b = current[0]
    return a*b if 1 <= offset+j-i-1 <= 5 else 0.


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        word, old, older, trace = '', ([], 1), ([], 1), (0., 0.)
    else:
        _, word, old, older, trace = carry
    token = prefix.token_strings[-1]
    points, n = vowel_positions(token)
    continues = bool(token) and all(
        c.isalpha() or unicodedata.category(c).startswith('M') for c in token)
    if not continues:
        word = ''
    ending = ''
    for char in token:
        if char.isalpha() or unicodedata.category(char).startswith('M'):
            ending += char
        else:
            ending = ''
    word = (word + ending)[-40:]
    now = skip = 0.
    if continues:
        now = pair_across(old[0], points, old[1]) / (max(2, n)*max(2, old[1]))
        if not old[0]:
            skip = pair_across(older[0], points, older[1]+old[1])
            skip *= .55**old[1] / (max(2, n)*max(2, older[1]))
    inside = sum(a*b for (i, a), (j, b) in zip(points, points[1:])
                 if 1 <= j-i-1 <= 5) / max(2, n)**2
    if not continues:
        inside *= .1
    if now or skip or inside:
        damp = unfamiliarity(word)
        now, skip, inside = now*damp, skip*damp, inside*damp
    fade = .65**n if continues else 0.
    tail, inner_tail = trace[0]*fade, trace[1]*fade
    value = -12.69*now - 7.64*skip - 12.08*inside
    value -= 8.25*tail + 35.22*inner_tail
    if first:
        value -= .93*sum(w for _, w in points)/max(2, n)
    if token and all(c == '·' for c in token):
        value = 1.247
    trace = (max(now, tail), max(inside, inner_tail))
    carry = (doc, word, (points, n), old, trace)
    return carry, max(-8., min(3., value))

"""A sparse detector of scraped-page boilerplate and source-code formatting.

Forum controls (Show/Hide Tags, permalink, Kudos), homework headings,
complexity labels, and a few code annotations give negative responses.
Diff hunk openers and code-file openings give positive responses. The
spelling and spacing matter: these are template fragments, not topics.
"""
import re

READS = ()

# Familiar labels, with the part already seen and the newly completed part.
LABELS = (
    ('Question', ' Stats', -2.25),
    ('Output', ' Format', -3.8),
    ('Input', ' Format', -3.2),
    ('Tools |', ' Templates', -0.83),
    ('View Full', ' Document', -0.55),
    ('LeetCode', ' Discuss', -4.6),
    ('Illuminate\\Http', '\\Response', -1.15),
    ('class', ' Solution', -1.2),
    ('end', '-of', 1.8),
    ('previous', ' approach', -0.9),
)
CODE_OPENERS = {'using', 'from', 'def', 'function', '#ifndef'}


def response(text, token, at_start):
    if token == ' Tags':
        if text.endswith('Show'):
            if '\xa0 [#permalink]\n\n' in text[-100:]:
                return -16.0
            if text.endswith('\n\n### Show') or text.endswith('\n\nShow'):
                return -9.0
            return -4.0
        if text.endswith('Hide'):
            return -5.0 if text.endswith('### Hide') else -3.6
    if token == 'permalink' and text.endswith('[#'):
        return -4.4
    if token == 'udos' and text.endswith('K'):
        if text.endswith('Own K'):
            return -2.4
        if text.endswith('Given K'):
            return -1.9
        if text.endswith('\n\nK'):
            return -3.7 if 'Followers:' in text[-100:] else -1.9
        return -1.8 if text.endswith('\nK') else -0.7

    if text.endswith('Homework'):
        heading = text.endswith('## Homework')
        if token == ' Equ':
            return -6.5 if heading else -4.9
        if token == ' Statement':
            return -3.8 if heading else -1.15
    if token == 'ations' and text.endswith('Homework Equ'):
        return -6.2 if text.endswith('## Homework Equ') else -3.3
    if token in {' Complexity', ' complexity'}:
        if re.search(r'\b(Time|Space)$', text):
            if token == ' complexity':
                return -2.3
            space = text.endswith('Space')
            if re.search(r'\* (Time|Space)$', text):
                return -4.7 if space else -3.1
            return -2.4 if space else -0.9
    if token == ' at':
        if text.endswith('Attempt'):
            return -0.76
        if text.endswith('The attempt'):
            return -0.23
    for before, completed, value in LABELS:
        if token == completed and text.endswith(before):
            return value

    if token == '@@':
        if re.search(r'\n\+\+\+ [^\n]*\n$', text):
            return 2.75
        return 1.25 if text.endswith('\n') else 0.36
    if token == ' coding' and text.endswith('#'):
        return 4.5
    if token == ' coding' and text.endswith('# -*-'):
        return 0.82
    if token == ' How' and text.endswith('#') and not text.endswith('##'):
        return 1.35
    if at_start:
        if token == 'package':
            return 1.43
        if token == 'import':
            return 0.83
        if token in CODE_OPENERS:
            return 1.4
        if token == '//\n':
            return 3.66
        if token in {'/*', '/*\n', '/**\n'}:
            return 0.9
    if token == '_modules' and text.endswith('node'):
        return -0.27
    if token == '.md':
        return -0.24
    if token == '.com' and text.endswith('github'):
        return -0.35
    if token and all(c == '·' for c in token):
        return -0.36 if len(token) > 1 else 0.001
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, at_start = '', True
    else:
        _, text, at_start = carry
    token = prefix.token_strings[-1]
    value = response(text, token, at_start)
    at_start = token == '<|endoftext|>'
    text = '' if at_start else (text + token)[-160:]
    return (doc, text, at_start), value

"""A sparse lexical detector, not a general semantic classifier.

The main positive cues are the Han characters for distance (远/遠),
permanence (永), and English 'young'. English 'yarn' and 'farther' have
negative responses. Compound Han tokens are weaker than isolated characters.
Comparison/distance collocations change the response, especially 'still'
and 'far' before comparisons, and 'yet another'. There are separate negative
cues for Australian state/institution names and a forum's 'Joined:' label.
Capitalization and splitting young/yarn across tokens change their strength.
Most positions return zero; idiosyncratic names and subwords are omitted.
UTF-8 fragments and document boundaries are handled incrementally.
"""
import codecs
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        decoder = codecs.getincrementaldecoder('utf-8')('ignore')
        previous = before = tail = ''
    else:
        _, decoder, previous, before, tail = carry
    text = decoder.decode(prefix.token_bytes[-1])
    word = text.strip()
    lower = word.lower()
    value = 0.0
    # Retain only the unfinished Latin word, for split all-capital spellings.
    match = re.search(r'[A-Za-z]+$', tail + text)
    tail = match[0][-12:] if match else ''

    if word in ('远', '遠', '远远', '遠遠'):
        value = 7.6 if '远' in word else 8.2
    elif '远' in word or '遠' in word:
        if len(word) > 2:
            value = 0.6
        elif word.startswith('永'):
            value = 5.5
        elif word.startswith('不'):
            value = 5.2
        elif word.startswith(('深', '长', '長')):
            value = 3.8
        else:
            value = 2.0
    elif word == '永':
        value = 3.5
    elif word == '久':
        value = 0.9
    elif word in ('永久', '长久', '長久'):
        value = 1.4
    elif lower == 'young':
        value = 1.5 if word[0].isupper() else 0.9
        if previous in ('a', 'in', 'very', 'so', 'too', 'really', 'still'):
            value = 1.35 if word.islower() else 1.5
    elif lower == 'yong':
        value = 2.0
    elif lower == 'yarn':
        value = -3.1 if word[0].isupper() else -0.85
    elif lower == 'farther':
        value = -1.7
    elif lower == 'another':
        value = -0.23
        if previous == 'still':
            value = -5.5
        elif previous == 'yet':
            value = -3.55
        elif previous == 'just':
            value = -1.2
        elif previous == 'quite':
            value = -1.8
    elif lower in ('different', 'similar'):
        value = 0.16

    if lower == 'way':
        if previous == 'a':
            value = 1.7 if before == 'such' else 0.5
        elif previous == 'long':
            value = 1.15
    if previous in ('way', 'ways') and lower == 'of':
        value = 0.85
    elif previous == 'far' and lower == 'from':
        value = 0.45
    elif previous == 'far' and lower == 'too':
        value = -0.9

    if lower == 'as' and previous == 'far':
        value = -3.2 if before == 'so' else -1.45
    if lower == 'more':
        if previous == 'still':
            value = -3.5
        elif previous == 'far':
            value = -2.7
        elif previous in ('ever', 'rather', 'increasingly'):
            value = -1.4
    if lower == 'away' and previous in ('far', 'stay'):
        value = 1.3
    if text == ':' and previous == 'joined':
        value = -0.85
    # Splitting these spellings across pieces produces a stronger response.
    if tail.lower().endswith('young') and lower != 'young':
        value = 3.8
    elif tail.lower().endswith('yong') and lower != 'yong':
        value = 2.0
    elif tail.lower().endswith('yarn') and lower != 'yarn':
        value = -2.2
    if tail in ('YOUN', 'YOUNG'):
        value = 4.7
    elif tail == 'YARN':
        value = -4.1

    if previous == 'still' and lower in ('further', 'others'):
        value = -4.4 if lower == 'further' else -2.8
    if previous == 'far' and lower in (
        'better', 'worse', 'higher', 'lower', 'greater', 'smaller',
        'larger', 'longer', 'shorter', 'less', 'further',
    ):
        value = -2.7
    if lower in ('australia', 'australian'):
        if previous in ('western', 'west', 'south'):
            value = -3.7
        elif previous == 'royal':
            value = -2.8

    return (doc, decoder, lower, previous, tail), value

"""Approximate a document-initial spelling pulse, strongest for early 'o'.

Only the initial repeated-token run receives the onset score. Transliteration
makes the spelling rule usable across scripts. Short o-spellings and capital O
are strongest; early a/i letters reduce the score. Spaces, case, and token form
adjust its baseline; message delimiters and digits have their own baselines.
Later, predict nearly zero except for 0 following 3 or 3-dot. This leaves
substantial token-specific variation unexplained rather than memorizing words.
"""
from anyascii import anyascii

READS = ()


def onset(token):
    if token in {'<|im_start|>', '<|im_end|>'}:
        return 5.35
    s = token.strip()
    if not s:
        return 0.4
    if s.isdigit():
        return 1.33 if s == '0' else -0.55

    word = anyascii(s).lower()
    leading_space = token.startswith(' ')
    value = 0.9 if s.isalpha() else 0.15
    value += 0.85 * leading_space + 0.65 * s.istitle()
    if s.isupper() and len(s) > 1:
        value += 0.4

    o = word.find('o')
    if o >= 0:
        value += (4.5, 4.5, 3.3, 1.1, 0.7)[min(o, 4)]
        if leading_space and o < 3:
            value -= (1.8, 2.1, 1.2)[o]
        if len(word) <= 3:
            value += (1.7, 1.4, 0.7)[len(word) - 1]
        if len(word) == 1 and s.isupper():
            value += 6.0

    # Early a/i spellings mildly counteract the onset pulse.
    for i, letter in enumerate(word[:4]):
        if letter in 'ai':
            value -= (0.95 if letter == 'a' else 0.75) * 0.7 ** i
    return value


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        initial_run = True
        previous = before_previous = ''
    else:
        _, previous, before_previous, initial_run = carry
        initial_run = initial_run and token == previous
    if initial_run:
        value = onset(token)
    elif token == '0' and previous.endswith('3'):
        value = 0.88
    elif token == '0' and previous == '.' and before_previous.endswith('3'):
        value = 0.52
    else:
        value = 0.03 if token == '0' else 0.0
    return (doc, token, previous, initial_run), float(value)

