programs.sol:
"""Recognize additions to a list or a parallel clause.

The largest outputs are at later item labels (2., (b), (ii)), at commas
ending discourse connectives, and at 'also'/'rather'. Smaller outputs
mark grammatical restarts after separators. The recent text is kept only
for recognizing these local constructions, and resets at documents.
Most other tokens get zero; repeated middle dots get a negative value.
These are local approximations, not a complete syntactic analysis.
"""
import re

READS = ()

ADDITIVE = set('also moreover furthermore additionally besides finally lastly '
               'similarly likewise plus'.split())
CONTRAST = set('however nevertheless nonetheless instead otherwise '
               'alternatively conversely'.split())
RESULT = set('therefore thus hence consequently accordingly'.split())
ORDER = set('second secondly third thirdly fourth fourthly fifth fifthly'.split())
PRONOUNS = set('i you he she it we they'.split())
COPULAS = set('is are was were be been being'.split())
MODALS = set('can could will would shall should may might must'.split())
DETERMINERS = set('the a an this these those that'.split())
PREPOSITIONS = set('of in on at by for from with into over under between'.split())
ROMAN = {'i': 1, 'ii': 2, 'iii': 3, 'iv': 4, 'v': 5,
         'vi': 6, 'vii': 7, 'viii': 8, 'ix': 9, 'x': 10}
HAN_NUMBERS = '一二三四五六七八九十'


def marker(before):
    m = re.search(r'([\d]+|[ivxIVX]+|[a-zA-Z]|[一二三四五六七八九十]+)$', before)
    if not m:
        return None
    label = m[1]
    lead = before[:m.start()]
    opened = lead.endswith(('(', '（', '['))
    if opened:
        lead = lead[:-1]
        if (lead and lead[-1].isalnum() and not lead.endswith('\\n')
                and not re.search(r'(?:and|or)$', lead)):
            return None
    elif lead and lead[-1].isalnum():
        return None
    # Do not confuse the end of a coordinate pair, such as (a,b), with (b).
    if not opened and lead.rfind('(') > lead.rfind(')'):
        return None
    if label.isdecimal():
        n = int(label)
        if not 1 <= n <= 999:
            return None
    elif label.lower() in ROMAN:
        n = ROMAN[label.lower()]
    elif label in HAN_NUMBERS:
        n = HAN_NUMBERS.index(label) + 1
    elif len(label) == 1 and label.isascii():
        n = ord(label.lower()) - ord('a') + 1
        if n > 8:
            return None
    else:
        return None
    line_start = bool(re.search(r"(?:^|\n|\\n)[\s>*\"'•]*$", lead))
    return n, opened, lead.rstrip(), line_start, label.isdecimal()


def predict(before, token, previous):
    word = token.strip().lower()
    prev = previous.strip().lower()
    # Item labels, unlike ordinary decimal points or closing parentheses.
    if token in (')', '）', '.', '．', '、', ']', ')$'):
        m = marker(before)
        if m:
            n, opened, lead, line_start, numeric = m
            later = n > 1
            scale = (2.0 / n) ** 0.4 if later else 1.0
            if token in ('.', '．', '、'):
                if lead.endswith((';', '；')):
                    return (2.8 * scale) if later else 0.0
                if line_start:
                    return (1.35 * scale) if later else 0.0
                if lead.endswith((';', '；', ':', '：')):
                    return (1.6 * scale) if later else 0.0
                return 0.0
            earlier_item = re.search(r'(?:[1-9a-h]|[ivx]+)\)', lead)
            if (opened or line_start or earlier_item
                    or re.search(r'(?:[.;:。；：]|\band|\bor)$', lead)):
                if not later:
                    return 1.8 if lead.endswith((':', '：')) else (0.5 if opened else 0.2)
                if re.search(r'[;；](?:\s*and)?$', lead):
                    value = 5.2
                elif re.search(r'\b(?:and|or|and that)$', lead):
                    value = 4.0
                elif lead.endswith((',', '，')):
                    value = 3.4
                elif line_start:
                    value = 2.25
                elif re.search(
                    r'(?:section|paragraph|clause|equation|eq\.?|figure|'
                    r'fig\.?|table|subsection)\s*$', lead, re.I
                ):
                    value = 0.4
                else:
                    value = 0.7 if numeric else 1.4
                if numeric and re.search(
                    r'(?:equation|eq\.|figs?\.|section|paragraph)'
                    r'[^;:\n]{0,25}$', lead, re.I
                ):
                    value = min(value, 0.8)
                return value * scale * (0.25 if token in (']', ')$') else 1.0)
    # A comma closing a short discourse introduction.
    if token in (',', '，', '、'):
        last = re.search(r'([A-Za-z]+)$', before)
        last = last[1].lower() if last else prev
        if last in ORDER:
            # Bare ordinals in 'per second,' or 'the second,' are not transitions.
            bare = last in ('second', 'third', 'fourth', 'fifth')
            if bare and before[-len(last):].islower():
                lead = before[:-len(last)].rstrip()
                if lead and lead[-1] not in ';:.\n':
                    return 0.0
            return 1.8
        if last in ADDITIVE:
            return 1.0
        if last in CONTRAST or last in RESULT:
            return 0.55
        if re.search(
            r'(?:for example|for instance|in fact|in particular|in addition|'
            r'in contrast|on the other hand|as a result|more importantly)$',
            before, re.I
        ):
            return 0.78
        if last in ('then', 'next', 'further', 'overall', 'and'):
            return 0.72
        if token == '、':
            if prev in ('また', 'さらに', 'そして'):
                return 1.3
            if prev in ('は', 'のは', 'に', 'と', 'で', 'には', 'では', 'も', 'ので', 'が'):
                return 0.35
