                strength = first_item_strength(item)
                strength *= math.exp(-0.0423 * max(0, distance - 2))
                strength *= math.exp(-0.0075 * max(0, len(item) - 12))
                strength *= 0.559 ** min(count, 8)
                if bracket == '[':
                    strength *= 0.486
                if '\n' in item:
                    strength *= 0.516
                stack[-1][3] += 1
            suffix, before = token[j + 1:], token[:j].strip()
            if j and before not in {'', '"', "'", ')', '()', ']', '\\"', "\\'"}:
                strength *= 0.474
            elif '\n' in token:
                strength *= 0.751
            elif len(suffix.strip()) > 1:
                strength *= 0.589
            value += strength
            if not suffix.strip() and '\n' not in token:
                echo, age = strength, 0
    return (doc, stack, last_open, echo, age), value

programs.haiku:
"""layers.1.mlp.down_proj:4886 -- a "lone word-start consonant" detector for non-Latin text.

It goes negative on a token that is a single space-led letter from Greek, Arabic or
Cyrillic (e.g. " κ", " м", " ش"): the tiny first piece of a longer non-Latin word, which
the tokenizer leaves split. Vowels and one-letter function words (Greek ηιοωυ; Cyrillic
аеёиоуыэюя, в, с) stay near zero. Broken UTF-8 fragments (U+FFFD) get a weaker negative.
Everything else is 0. Values are rough mean activations, not fitted per token.
"""
import unicodedata

READS = ()

# typical mean activation of such a lone letter, by script
SCRIPT_VALUE = {"GREEK": -1.7, "ARABIC": -1.5, "CYRILLIC": -1.3}
# letters of each script that do not fire: vowels and one-letter words
QUIET = {"GREEK": "ηιοωυ", "CYRILLIC": "аеёиоуыэюяв с"}


def _script(ch):
    try:
        return unicodedata.name(ch).split()[0]
    except ValueError:
        return ""


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    value = 0.0
    if len(s) == 2 and s[0] == " " and s[1].isalpha():
        script = _script(s[1])
        if script in SCRIPT_VALUE and s[1].lower() not in QUIET.get(script, ""):
            value = SCRIPT_VALUE[script]
    elif "�" in s:
        value = -0.3 if s.startswith(" ") else -0.1
    return carry, float(value)

programs.sol:
"""Recognize continuations of letter-named mathematical/scientific expressions.

A letter followed by an operator gives a negative response, especially x/y/z.
Coordinate descriptions and statistical letter-names give larger responses.
Spelling can cross token boundaries (as in x-co + ordinates). Powers give a
smaller response. Ordinary prose and unrecognized continuations default to zero.
"""
import re

READS = ()
COORDINATE = ('coordinate', 'coordinates', 'coord', 'coords', 'axis', 'axes',
              'direction', 'directions', 'plane', 'intercept', 'intercepts',
              'interval', 'intervals')
MEASURE = ('value', 'values', 'val', 'vals', 'score', 'scores',
           'term', 'terms', 'component', 'components', 'coefficient',
           'coefficients', 'min', 'max', 'squared', 'cubed')
BIOLOGY = ('cell', 'cells', 'terminal', 'terminus', 'type')
GREEK_NAMES = {'alpha', 'beta', 'gamma', 'delta', 'theta', 'lambda',
               'sigma', 'omega'}
DELIMITERS = ' \t$*`\'"“”‘’–-_'  # wrappers around a letter-name


def variable(token):
    s = token.strip()
    if s in ('\\n', '\\t', '\\r') or s.startswith('<'):
        return ''
    s = s.strip(DELIMITERS)
    if s in GREEK_NAMES:
        return 'α'
    m = re.search(r'([^\W\d_]+)$', s)
    if not m:
        return ''
    w = m[1]
    if len(w) == 1 and (w.isascii() or 'α' <= w <= 'ω' or 'Α' <= w <= 'Ω'):
        return w
    if len(w) == 2 and (set(w.lower()) <= set('xyz') or
                       (w[0].isupper() and w[1] in 'xyz')):
        return w[-1]
    return ''


def operator_strength(letter, op):
    low = letter.lower()
    if op == '=':
        if low in 'xyz':
            return {'x': 1.6, 'y': 2.2, 'z': 1.5}[low]
        if low in 'npqkt':
            return 1.8
        if low in 'abmrs':
            return 1.1
        return 0.3 if low == 'i' else 0.65
    if op == '+':
        if low in 'xyznpk':
            return 2.3 if low == 'x' else 1.8
        return 0.2 if low in 'ij' else 1.25
    if op in '-−':
        if low in 'xyzpkt':
            return 2.6 if low == 'x' else 1.7
        return 0.8 if low in 'abcdems' else 0.35
    if op == '^':
        return 0.8 if low == 'x' else 0.5 if low in 'yznkp' else 0.2
    if op == '_':
        return 0.2 if low in 'xntp' else 0.05
    if op in '<≤':
        return 3.5 if low == 'p' else 0.6 if low in 'xyzqt' else 0.15
    if op in '>≥':
        return 1.5 if low == 'p' else 0.4
    return 0.0


def phrase_strength(letter, spelling, partial):
    """Return the strength and whether a recognized word is still being spelled."""
    low = letter.lower()
    groups = [(COORDINATE, 5.0 if low in 'xyz' else 1.5),
              (MEASURE, 4.8 if low in 'pxyzrt' else 2.0),
              (BIOLOGY, 3.2 if low in 'tbnc' else 1.0),
              (('test', 'tests'), 5.0 if low == 't' else 1.0),
              (('ray', 'rays'), 4.0 if low in 'xα' else 0.8)]
    if letter in ('a', 'I') and spelling not in ('squared', 'cubed'):
        return 0.0, False
    if len(spelling) < 2 and not (spelling == 'c' and letter in 'TB'):
        return 0.0, False
    for words, strength in groups:
        if spelling in words or (partial and any(w.startswith(spelling) for w in words)):
            if spelling in ('squared', 'cubed'):
                strength = 1.5
            return strength, True
    return 0.0, False


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, name, fragment = (), '', ''
    else:
        _, history, name, fragment = carry
    token = prefix.token_strings[-1]
    s = token.lstrip()
    value, continuing = 0.0, False
    spelling = ''
    previous_name_hyphen = bool(history and history[-1].endswith(('-', '_', '–')))
    if name:
        if not fragment and s and not s.startswith(('==', '=>', '+=', '-=')):
            value = -operator_strength(name, s[0])
            if s[0] in '<>' and any(c.isalpha() for c in s):
                value *= 0.15
            if s[0] == '=' and name == 'n':
                if re.search(r'\(\s*n\s*$', ''.join(history)):
                    value = -4.0
        if not fragment or not token[:1].isspace():
            spelling = fragment + s.strip(DELIMITERS).lower()
            partial = bool(fragment) or s.startswith(('-', '_')) or previous_name_hyphen
            strength, continuing = phrase_strength(name, spelling, partial)
            if continuing:
                value = -strength
    previous = history[-1] if history else ''
    if not name and s.startswith(('=', '+', '-', '−')):
        if previous and all(c in '²³⁰¹⁴⁵⁶⁷⁸⁹₀₁₂₃₄₅₆₇₈₉′' for c in previous):
            value = -0.9
        elif previous.isdigit() and len(history) >= 3:
            if history[-2] in ('^', '**') and variable(history[-3]):
                value = -0.65
        elif previous.isspace() and '\xa0' in previous:
            value = -1.5
    new_name = variable(token)
    if (token[:1].isalpha() and history and history[-1][-1:].isalpha()
            and not (new_name in 'xyzXYZ' and new_name and
                     variable(history[-1]) in ('x', 'y', 'z', 'X', 'Y', 'Z'))):
        new_name = ''
    if (''.join(history[-2:]) + token).endswith('size_t'):
        new_name = ''
    if continuing:
        fragment = spelling
    elif new_name:
        name, fragment = new_name, ''
    elif name and token and all(c in DELIMITERS for c in token):
        pass
    else:
        name, fragment = '', ''
    return (doc, (history + (token,))[-3:], name, fragment), value

programs.haiku:
"""layers.1.mlp.down_proj:4887 — "a single-letter symbol, then an operator or a technical word".

This component turns negative when the token just read is an operator or a technical word
that follows a single-letter math or statistics symbol: `x = `, `n =`, `p <`, `y + `, `z-score`,
`x-coordinate`, `t test`, `r value`, `x-axis`. Its size is largest for the sign after a
letter that names a quantity or coordinate (p, x, y, z, n, t, r, q), and for the second
half of a fixed two-part term. It is near zero everywhere else, including letters inside
ordinary words, numbers before operators, and abbreviations like SD or CI.

The program needs no state beyond the previous token, so it reads only the last two tokens.
"""

READS = ()

# Arithmetic and comparison signs that follow a symbol.
MAIN_OPS = set("+=-<−")
# Minor signs: exponent and greater-than.
MINOR_OPS = set("^>")
# Letters that usually name a quantity or a coordinate in maths and statistics.
STRONG_LETTERS = set("pxyzntrqPYt")
# Second halves of two-part technical terms: z-score, x-coordinate, t-test, p-value, x-axis, ...
TERM_WORDS = {
    "score", "coordinate", "coordinates", "inter", "test", "tests", "value", "values", "Value",
    "direction", "axis", "ray", "rays", "type", "index", "cell", "cells", "plane",
}


def is_symbol(token):
    """A single letter, possibly inside a bracket or a dollar sign, or a superscript 2 or 3."""
    token = token.strip().lstrip("($\\{")
    return (len(token) == 1 and token.isalpha()) or token in ("²", "³")


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    prev, cur = prefix.token_strings[-2], prefix.token_strings[-1]
    if not is_symbol(prev):
        return None, 0.0
    word = cur.strip()
    if word.lstrip("-") in TERM_WORDS:
        # A hyphenated term (x-axis) is stronger than a spaced one (x axis).
        return None, (-5.0 if cur.startswith("-") else -1.5)
    strong = prev.strip().lstrip("($\\{") in STRONG_LETTERS
    if word in MAIN_OPS:
        return None, (-2.0 if strong else -1.0)
    if word in MINOR_OPS:
        return None, (-0.6 if strong else -0.25)
    return None, 0.0

programs.sol:
"""Coordinating words, especially coordination of English verb phrases.

English and/or get boosts after punctuation, words ending in -ed/-ing,
and dictionary verbs following 'to', a modal, or an auxiliary. Several translations
have stronger lexical responses; recent word frequencies distinguish those
from letters in formulas and fragments of other words. Greek conjunctions
may finish across tokens. Arbitrary document-initial transients are omitted.
"""
import re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()

# Coordinating words: languages in which they coordinate, and response size.
COORDINATORS = {
    'e': (('it', 'pt'), 1.45),
    'ed': (('it',), 1.75),
    'y': (('es',), 1.45),
    'et': (('fr',), 1.10),
    'und': (('de',), 0.85),
    'og': (('da', 'nb'), 1.35),
    'och': (('sv',), 1.30),
    've': (('tr',), 1.00),
    'i': (('pl',), 0.90),
    'ja': (('fi',), 1.60),
    'ou': (('fr', 'pt'), 0.65),
    'și': (('ro',), 1.05),
    'şi': (('ro',), 1.05),
    'si': (('ro',), 1.70),
    'en': (('nl',), 1.20),
    'o': (('it', 'es'), 0.70),
}
MODALS = {'can', 'could', 'will', 'would', 'shall', 'should', 'may', 'might', 'must'}
AUXILIARIES = {'have', 'has', 'had', 'is', 'are', 'am', 'was', 'were', 'be', 'been'}


@lru_cache(maxsize=20000)
def frequency(word, language):
    return zipf_frequency(word, language)


@lru_cache(maxsize=20000)
def parts(word):
    return wordnet.parts_of_speech(word)


def language_evidence(words, languages, alternatives):
    if not words:
        return -1.0
    def score(language):
        return sum(frequency(w, language) for w in words) / len(words)
    return max(map(score, languages)) - max(map(score, alternatives))


def english_response(token, history, previous, inside):
    words = re.findall(r'[^\W\d_]+', history.lower())
    last = words[-1] if words else ''
    pos = parts(last)
    before = words[:-1]
    if before and ('adverb' in parts(before[-1]) or before[-1] == 'not'):
        before = before[:-1]
    anchor = before[-1] if before else ''
    w = token.strip()
    value = 0.22 * w.istitle() + 0.14 * w.isupper()
    value += 0.20 * (not token.startswith(' ')) - 0.27 * inside
    value += 0.19 * (',' in previous)
    value += 0.15 * any(c in previous for c in '.!?')
    value += 0.17 * any(c in previous for c in ':;')
    value += 0.05 * any(c in previous for c in '()[]"')
    value += 0.13 * previous.isspace()
    value += 0.10 * ('verb' in pos) - 0.04 * ('noun' in pos)
    value -= 0.01 * ('adjective' in pos)
    value += 0.24 * last.endswith('ed') + 0.18 * last.endswith('ing')
    if 'verb' in pos:
        value += 0.47 * (anchor == 'to' or anchor in MODALS)
        value += 0.08 * (anchor in AUXILIARIES)
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = () if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    w = token.strip()
    lower = w.lower()
    value = 0.0
    if lower in {'and', 'or'} or lower in COORDINATORS or lower == 'و':
        history = ''.join(recent)
        previous = recent[-1] if recent else ''
        inside = not token[:1].isspace() and bool(re.search(r'\w$', history))
        if lower in {'and', 'or'}:
            value = english_response(token, history, previous, inside)
        elif not inside:
            if lower == 'و':
                value = 0.85
            else:
                languages, strength = COORDINATORS[lower]
                words = re.findall(r'[^\W\d_]+', history.lower())[-8:]
                alternatives = {
                    'o': ('en', 'pt'), 'si': ('en', 'fr', 'es', 'it'),
                    'en': ('en', 'fr', 'es', 'de'),
                }.get(lower, ('en',))
                if lower == 'und':
                    value = 0.25
                if language_evidence(words, languages, alternatives) > 0.5:
                    value = strength + 0.35 * w.istitle() * (len(w) > 1)
    elif token.endswith(('αι', 'ὶ', 'ι')):
        ending = (''.join(recent) + token).lower()
        if re.search(r'(?:^|\W)και$', ending):
            value = 2.4
        elif re.search(r'(?:^|\W)καὶ$', ending):
            value = 1.8
    recent = () if token == '<|endoftext|>' else (*recent[-11:], token)
    return (doc, recent), value

programs.haiku:
"""Layer 1, MLP down-projection, component 4889: a "coordinating 'and'" detector.

In plain terms, the component fires on the word for "and" when it links two items or two
verbs, and it fires much more strongly when the word is "and" in a language other than
English.

1. Foreign-language "and" (the main effect). Words such as German "und", Danish/Norwegian
   "og", Swedish "och", French/Latin "et", Spanish "y", Italian/Portuguese "e", French
   "ou", Turkish/Portuguese "ve", Romanian "și", Arabic "و" give a strong response
   (about 0.3 to 1.3). It is switched off when the recent text is English (the last 20
   tokens contain no common English word), weaker when there is a little English, and
   stronger right after a comma (", e io", ", et"). Spanish "y" fires; French "il y a"
   (where "y" is not a conjunction) does not.

2. English "and" (weak). It is near zero in general, but rises after a comma, after a
   verb-like word ("identify and", "created and", "collect and"), or two words after an
   infinitive marker or modal ("to store and use", "you can plan and conduct"). A
   sentence-initial "And" is moderately strong.

3. First token of a document (no earlier context, so the response depends on the token
   itself). A document that opens with code or markup ("#", "//", "/*", "@", "\\", "^")
   gives a strong response, as do code keywords ("package", "import", "export", "def"),
   a leading " the", and symbols outside ASCII. A chat marker such as "<|im_start|>" is
   slightly negative. Other document openings are predicted as 0.

Everything else is predicted as 0. The program is a rule set over the newest token and its
recent context; it needs no state carried between positions.
"""

READS = ()

# Coordinating "and" words in other languages, with their typical activation when the
# surrounding text is not English.
FOREIGN_CONJ = {
    "og": 1.2, "och": 1.1, "și": 1.0, "şi": 1.3, "und": 0.9, "і": 0.9, "dan": 0.75,
    "és": 0.7, "و": 0.67, "ou": 0.6, "et": 0.6, "ja": 0.55, "e": 0.55, "y": 0.5,
    "ve": 0.5, "oder": 0.5, "ed": 0.5, "и": 0.5, "eller": 0.45, "và": 0.4, "или": 0.3,
}
# Common English words, used to tell whether the recent text is English.
ENGLISH_WORDS = {
    "the", "of", "and", "to", "is", "that", "with", "for", "was", "it", "are", "this",
    "be", "on", "as", "by", "you", "or", "have", "from", "an",
}
VERB_ENDINGS = ("ed", "ing", "ify", "ize", "ise", "ate")
VERB_CUES = {"to", "can", "will", "would", "should", "could", "must", "we", "you", "they", "how"}
CODE_START = "#/\\@*^"  # a document opening with one of these looks like code or markup
CODE_WORDS = {"package", "import", "export", "def", "namespace", "using"}
WINDOW = 20  # how many earlier tokens we look at for English context


def _is_doc_start(prefix):
    t = prefix.position
    return t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]


def _doc_start_value(token):
    word = token.strip()
    if word.startswith("<|"):
        return -0.2  # special marker such as <|im_start|>
    if not word:
        return 0.0
    if word in CODE_WORDS:
        return 2.5
    if token == " the":
        return 0.7
    first = word[0]
    if first in CODE_START:
        return 1.7
    if first in "_-[!`":
        return 0.6
    if not first.isascii() and not first.isalpha():
        return 1.4  # a non-Latin symbol
    return 0.0


def _english_and(token, before, before2):
    if token.strip() == "And":
        return 0.45
    if before == ",":
        return 0.25
    if before.isalpha() and before.endswith(VERB_ENDINGS):
        return 0.4
    if before2 in VERB_CUES:
        return 0.45
    return 0.03


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    t = prefix.position
    if _is_doc_start(prefix):
        return carry, _doc_start_value(token)

    before = prefix.token_strings[-2].strip().lower() if t > 0 else ""
    before2 = prefix.token_strings[-3].strip().lower() if t > 1 else ""

    if word == "and":
        return carry, _english_and(token, before, before2)

    if word in FOREIGN_CONJ and token[:1] == " ":
        if word == "y" and before == "il":
            return carry, 0.0  # French "il y a"
        recent = prefix.token_strings[max(0, t - WINDOW):t]
        english = sum(1 for s in recent if s.strip().lower() in ENGLISH_WORDS)
        boost = 1.5 if before == "," else 1.0
        if english == 0:
            return carry, boost * FOREIGN_CONJ[word]
        if english <= 2:
            return carry, 0.4 * boost * FOREIGN_CONJ[word]
    return carry, 0.0

programs.sol:
"""Approximate a negative passive-participle feature.

Participles after be/get receive negative values, allowing intervening
adverbs and coordinated verbs. Internal word fragments and rarer regular
verbs are stronger. Directional phrasal verbs and selected prepositional
passives also fire at their final word. Weak suffix-only rules cover some
other European participles. This is surface grammar, not a full parser.
"""
import re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()
BE = set('be been being is are am was were get gets got getting'.split())
HAVE = set('have has had having'.split())
MODIFIERS = set('not never ever also just still already then once often only '
                'even always sometimes again well'.split())
NOT_PARTICIPLES = set('went saw took ate gave drove wrote spoke broke fell '
                     'flew ran sang drank swam began chose knew grew drew '
                     'threw wore did was were has had does is'.split())
UNCHANGED = set('put cut set read hit hurt let cast spread split shut cost '
                'burst run come become overcome bet quit rid shed'.split())
DIRECTIONAL = set('up down out off away back over apart through around'.split())
FRENCH_BE = set('être est sont était étaient été sera seront soit soient'.split())
# These verbs take a prepositional object, which can itself be passivized.
PREPOSITIONAL_OBJECTS = {
    ('think', 'of'), ('look', 'at'), ('look', 'upon'), ('dispose', 'of'),
    ('deal', 'with'), ('act', 'upon'), ('account', 'for'),
}

@lru_cache(maxsize=30000)
def past(word):
    if word in UNCHANGED or len(word) > 3 and word.endswith('ed'):
        return True
    return bool(word and word not in NOT_PARTICIPLES
                and not word.endswith(('ing', 's'))
                and any(b != word for b in wordnet.base_forms(word, 'verb')))

@lru_cache(maxsize=30000)
def modifier(word):
    return (word in MODIFIERS or word.endswith('ly')
            or 'adverb' in wordnet.parts_of_speech(word))

@lru_cache(maxsize=30000)
def rare(word):
    return zipf_frequency(word, 'en') < 4.5


def activation(text, token):
    clause = re.split(r'[.!?;\n]', text)[-1].lower().replace('’', "'")
    words = re.findall(r"[^\W\d_]+(?:'[^\W\d_]+)?", clause)
    w = words[-1] if words and token[-1:].isalpha() else ''
    if not w:
        return 0.0
    prev = words[:-1]
    prev = [x[:-3] if x.endswith("n't") else x for x in prev]
    prev = ['is' if x.endswith("'s") else
            'are' if x.endswith("'re") else x for x in prev]
    distance = next((i + 1 for i, x in enumerate(reversed(prev[-8:]))
                     if x in BE), 9)
    aux = prev[-distance] if distance < 9 else ''
    between = prev[-distance + 1:] if 1 < distance < 9 else []
    direct = bool(aux) and all(modifier(x) for x in between)
    coordinated = bool(aux and between) and all(
        modifier(x) or past(x) or x in {'and', 'or'} for x in between)

    # A final particle can complete a passive verb: 'was picked UP'.
    if aux:
        for size in (2, 3):
            if len(words) < size or distance < size:
                continue
            phrase = tuple((prev + [w])[-size:])
            before = prev[-distance + 1:len(prev) - size + 1]
            if not past(phrase[0]) or not all(
                    modifier(x) or past(x) or x in {'and', 'or'} for x in before):
                continue
            for base in wordnet.base_forms(phrase[0], 'verb'):
                if size == 2 and (base, w) in PREPOSITIONAL_OBJECTS:
                    return -5.0
                if 'verb' in wordnet.parts_of_speech(' '.join((base,) + phrase[1:])):
                    return -2.6 if w in DIRECTIONAL else -0.7

    if past(w):
        regular = len(w) > 3 and w.endswith('ed')
        if direct:
            if regular:
                if aux in {'is', 'are', 'am'}:
                    value = -1.65 if rare(w) else -1.30
                    return value - (0.45 if token[:1].isalpha() else 0.0)
                if token[:1].isalpha():
                    return -3.0
                return -2.17 if rare(w) else -1.78
            return -1.23 if aux in {'is', 'are', 'am'} else -1.74
        if coordinated:
            return -2.54 if regular else -1.79
        if prev and prev[-1] in {'when', 'if', 'once', 'unless', 'as'}:
            return -1.0
        if distance <= 4:
            return -0.53 if regular else -0.17
        if any(x in HAVE for x in prev[-2:]):
            return 0.0
        return -0.30 if regular else -0.04

    french = w.endswith(('é', 'ée', 'és', 'ées'))
    if french and any(x in FRENCH_BE for x in prev[-4:]):
        return -1.0
    romance = w.endswith(('ado', 'ada', 'ados', 'adas', 'ido', 'ida', 'idos', 'idas'))
    german = len(w) > 4 and w.startswith('ge') and w.endswith(('t', 'en'))
    return -0.16 if french or romance or german else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = b'' if carry is None or carry[0] != doc else carry[1]
    tail = (tail + prefix.token_bytes[-1])[-720:]
    text = tail.decode('utf-8', errors='replace')[-180:]
    value = activation(text, prefix.token_strings[-1])
    return (doc, tail), float(value)

"""A recent-digit-pair response, concentrated on the thirties and forties.

Adjacent decimal digits 30--46 have a negative response, deepest around
35--44; 48--49 reverse its sign. The second digit of a number is strongest,
and later digits are weaker. Decimal points preserve more of the response
than commas, spaces, or range separators. Non-digits predict zero.
The curves approximate training observations, not vocabulary-token tables.
"""

import unicodedata

READS = ()


def pair_response(tens, units):
    if tens == 3:
        return (-0.7 - 0.6 * min(units, 3)
                - 1.8 * min(max(0, units - 3), 1)
                + 0.8 * max(0, units - 6))
    if tens == 4:
        return (-4.05 - 1.1 * max(0, 1 - units)
                + 1.05 * max(0, units - 4)
                + 0.9 * max(0, units - 6)
                - 0.65 * max(0, units - 8))
    if tens == 9:
        return min(0.0, -1.45 + 0.165 * units)
    if tens == 2:
        return -0.18 * max(0, units - 6)
    if tens == 6:
        return -0.15 * max(0, units - 4)
    return 0.0


def separator_strength(text):
    if text == '.':
        return 0.48
    if text == ',':
        return 0.32
    if text in (' ', ':', '-', '/'):
        return 0.13
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, None, 0, '', 1.0)
    _, previous, length, gap, boundary_gain = carry
    text = prefix.token_strings[-1]
    if len(text) == 1 and text.isdecimal():
        digit = unicodedata.decimal(text)
        value = pair_response(previous, digit)
        if gap or previous is None:
            length = 1
            before = (prefix.token_strings[-2]
                      if prefix.position and prefix.document_ids[-2] == doc
                      else '')
            boundary_gain = 0.85 if '.' in before or ',' in before else 1.0
            value *= separator_strength(gap)
        else:
            length += 1
            length_gain = (1.14 if length == 2 else
                           0.88 if length == 3 else 0.76)
            value *= length_gain * boundary_gain
        return (doc, digit, length, '', boundary_gain), float(value)
    if previous is not None and not gap and separator_strength(text):
        return (doc, previous, 0, text, 1.0), 0.0
    return (doc, None, 0, '', 1.0), 0.0

"""Approximate a title/subtitle boundary signal.

Colons get their largest positive values after runs of capitalized title
words, rather than inside identifiers, numeric notation, or common metadata
fields. A following article can inherit some of that signal. There are
also fixed responses to edition/addition and formal linking phrases,
contextual responses to with/using, and a document-initial offset.
Everything else is zero.
Only a short recent text buffer is retained; documents reset all state.
"""
import re

READS = ()
PARTICLES = set(
    'a an the and or of in on at to for from with by as via de la le et'.split()
)
# Common heads of metadata fields, credit lists, and forum counters.
FIELD_HEADS = set(
    'name title type code date time version encoding language tag address '
    'location status id key value url path length count result input output '
    'source post view comment reply kudos director officer designer agency'.split()
)
WORDS = re.compile(r'[^\W\d_]+')


def title_cues(text):
    line = text.rsplit('\n', 1)[-1]
    fragment = re.split(r'[.!?:;{}=\\`<>\[\]]', line)[-1]
    words = WORDS.findall(fragment)[-14:]
    cap = lambda w: w[0].isupper() and not w.isupper()
    capitals = sum(cap(w) for w in words)
    lower = sum(w.islower() and w not in PARTICLES for w in words)
    run = 0
    for word in reversed(words):
        if cap(word):
            run += 1
        elif word.lower() in PARTICLES or re.fullmatch('[IVXLCDM]+', word):
            continue
        else:
            break
    clean = not re.search(r'[a-z][A-Z]|[a-z]_[a-z]|\d$', fragment)
    return words, capitals, lower, run, clean


def colon_value(text, token):
    if token.strip() not in (':', '):', '”:', '":'):
        return 0.0
    words, capitals, lower, run, clean = title_cues(text)
    if words:
        head = words[-1].lower()
        if head in FIELD_HEADS or (head.endswith('s') and head[:-1] in FIELD_HEADS):
            return 0.0
    if not clean:
        return 0.0
    if run >= 4:
        return 1.10
    if run >= 2:
        return 0.70
    if capitals >= 2 and lower <= 2:
        return 0.35
    if capitals >= 1 and lower <= 2 and len(words) >= 2:
        return 0.05
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    if initial:
        text, boundary = '', 0.0
    else:
        _, text, boundary = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if initial:
        value = 0.27 if any(c.isalpha() for c in token) else 0.10
    if ':' in token:
        value = colon_value(text, token)
        boundary = max(value, 0.0)
    elif token.isspace() or token.strip() in ('"', '“', "'"):
        pass
    else:
        if word in ('edition', 'editions'):
            value += 0.70
        elif word == 'addition':
            value += 0.26
        elif word == '之':  # Formal Chinese possessive/linking particle.
            value += 0.20
        elif word == 'ために':  # Japanese 'for / in order to'.
            value += 0.65
        elif word in ('with', 'using'):
            _, _, _, run, clean = title_cues(text)
            if run >= 2 and clean:
                value += 0.20
        if boundary and word in ('a', 'an', 'the'):
            value += 0.60 * boundary
        boundary = 0.0
    return (doc, (text + token)[-240:], boundary), float(value)

programs.haiku:
"""Title colons (layers.1.mlp.down_proj:4893).

This component reads the layer-1 MLP and writes a small signal. What it tracks, in plain
terms, is the title of a book, paper, article or product, and the start of the subtitle
that follows:

- the colon that ends a title ("Odd Girls and Twilight Lovers:", "Mafia III:") fires;
  it fires most when the title has a small word inside it ("and", "of", "in", ...);
- the first word of the subtitle after such a colon fires a little;
- the word "edition" (and, weaker, "addition") fires, as it often does in titles;
- the first token of each document fires moderately, on average.

Colons in key-value labels ("Country: India") and in times or ratios ("9:30") stay at 0.

The program is a plain rule set over the text of the current line. Its carry holds the
current line (since the last newline, reset at each document) and whether the previous
token was a title colon. Values are the rounded group means measured on training rows.
"""
import re

READS = ()

START_VALUE = 0.22       # first token of a document
TITLE_COLON = 0.3        # ':' ending a title of 2+ capitalised words, no sentence end
TITLE_COLON_SMALL = 0.8  # the same title, with a small word ("and", "of", ...) inside
SUBTITLE_WORD = 0.1      # first word after a title colon
EDITION_WORD = 0.7       # 'edition'
ADDITION_WORD = 0.27     # 'addition'
SMALL_WORDS = {"and", "of", "in", "for", "with", "the", "to", "on", "a", "an", "vs",
               "from", "by", "at", "or", "as"}


def title_colon_value(line):
    """How strongly a colon right after `line` ends a title."""
    words = line.split()
    if len(words) < 3 or re.search(r"[.!?]\s", line):
        return 0.0
    if sum(w[0].isupper() for w in words) < 0.6 * len(words):
        return 0.0
    if any(w.lower().strip(",") in SMALL_WORDS for w in words[1:-1]):
        return TITLE_COLON_SMALL
    return TITLE_COLON


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        line, after_title_colon = "", False
    else:
        line, after_title_colon = carry
    is_colon = token.strip() == ":"
    colon_value = title_colon_value(line) if is_colon else 0.0
    if "\n" in token:
        line = token.split("\n")[-1]
    else:
        line += token
    if new_doc:
        value = START_VALUE
    elif colon_value > 0:
        value = colon_value
    elif after_title_colon:
        value = SUBTITLE_WORD
    elif token.strip().lower() == "edition":
        value = EDITION_WORD
    elif token.strip().lower() == "addition":
        value = ADDITION_WORD
    else:
        value = 0.0
    return (line, colon_value > 0), value

programs.sol:
"""Sparse word and phrase completions, with a 160-character memory.

Positive responses cover limitation(s), licenses, spellings of Allah,
negated or questioned 'have', 'only thing', and selected 'all ...' phrases.
'All rights' and several other 'all ...' endings are negative, as are
repeated middle-dot leaders. Arabic vowel marks are ignored for matching.
Everything else is zero; state resets at each document boundary. This
intentionally omits many rare name and multilingual word-fragment effects.
"""
import re
import unicodedata

READS = ()

# These are phrase endings, not standalone-word scores.
AFTER_ALL = {
    'rights': -6.3,
    'day': -2.6,
    'week': -2.0,
    'but': -3.0,
    'you': -1.9,
    'we': -1.4,
    'i': -0.4,
    'other': 1.3,
    'things': 5.0,
    'about': 1.5,
    'times': 1.8,
    'people': 2.2,
    'authors': 3.0,
}


def response(token, before, previous):
    word = token.strip().lower()
    text = (before + token).lower()
    if token == '··' and previous == token:
        return -1.025
    if re.search(r'\blimitations?\Z', text):
        if token.strip().lower() not in ('limitation', 'limitations'):
            return 5.5  # completion across a token boundary
        if token.lstrip()[0].isupper():
            return 5.7
        return 5.3 if 'permissions' in before[-100:].lower() else 3.4
    if token.strip() == 'License':
        if re.search(r'limitations\s+under\s+the\s*$', before.lower()):
            if '*' in before[-40:] or '//' in before[-40:]:
                return 11.2
            return 13.0 if 'permissions and limitations' in before.lower() else 6.0
        if re.search(r'(public|attribution|international|mit)\s*$', before.lower()):
            return 5.3
        if before.lower().endswith('apache'):
            return 2.5
        if re.search(r'under\s+the\s*$', before.lower()):
            return 3.6
        if previous.strip().lower() == 'the':
            return 2.0
        return 0.5
    if token == '/licenses' and before.endswith('gnu.org'):
        return 9.0
    if re.search(r'\b(allah|wallah|vallahi|billahi)\Z', text):
        return 6.6 if word == 'allah' else 9.5
    if 'ه' in token or (token and unicodedata.combining(token[-1])):
        bare = ''.join(c for c in text if not unicodedata.combining(c))
        if bare.endswith(('الله', 'لله')):
            if not any(c.isalpha() for c in token):
                return 5.8
            if word == 'الله':
                return 8.0
            if word == 'والله':
                return 4.3
            return 12.0
    if previous.strip().lower() == 'all':
        return AFTER_ALL.get(word, 0.0)
    if word == 'thing' and previous.strip().lower() == 'only':
        return 3.2
    if word == 'have':
        if re.search(r'\b(do|does|did)\s+not\s+have$', text):
            return 3.2
        if re.search(r'\b(don|doesn|didn)[\x27’`]t\s+have$', text):
            return 1.5 if previous.isupper() else 2.7
        if re.search(r'\b(do|does)\s+(i|you|he|she|it|we|they|u)\s+have$', text):
            return 1.7
        if previous.strip().lower() in ('do', 'does', 'did', 'only'):
            return 1.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, previous = '', ''
    else:
        _, before, previous = carry
    token = prefix.token_strings[-1]
    value = response(token, before, previous)
    return (doc, (before + token)[-160:], token), value

programs.haiku:
"""Layer 1, MLP hidden unit 4894 (this component reads just that unit, V is its basis vector).

Its activation is a sparse, word-specific detector. Nearly everywhere it is about 0; it jumps
on a few concepts seen in training text:

  * "have" right after a negation ("do not have", "don't have", "never have"): positive, ~+2.
  * " License" (as in "under the License") and " limitation(s)" (as in "the limitations under
    the License", the Apache/MIT boilerplate): positive, ~+3.5.
  * "Allah" and its spelled-out pieces ("All"+"ah", "Vall"+"ahi", Arabic "الله"): strongly positive, ~+8.
  * "rights" right after "All" ("All rights reserved"), and "All Saints": strongly negative, ~-6.
  * "all" + "day" / "but" / "you": negative, ~-2.6.
  * "all" or "only" + "thing(s)" / "other" / "times" / "about": positive, ~+2.5.
  * a run of middle dots "··": a constant ~-1.

Everything else predicts 0. The rules are keyed on the token just decoded and the token before it,
so the program needs no state beyond the previous token.
"""

READS = ()

NEGATION = {" not", " never", "n't", "'t", "’t"}
LICENSE = {" License", "licenses", "/licenses"}
LIMITATION = {" limitation", " limitations", "ation", "ations"}
LIMITATION_BEFORE = {" the", " and", " other", " without", " this", " *", " Limit", "Limit", "limit"}
ALLAH_TAILS = {"ah", "ahi", "ahan", "ahas", "lah", "ahu"}
ALLAH_STEMS = {"All", "Vall", "Tall", "Call", "Mall", "El", "AL", "al", "ALl", "ALL"}
ALL = {"All", " All", " all"}
QUANTIFIER_NEXT = {" thing", " things", " other", " times", " about"}
QUANTIFIER_BEFORE = {" all", " All", "All", " only"}


def step(carry, prefix, upstream):
    s = prefix.token_strings
    i = len(s) - 1
    t = s[i]
    p = s[i - 1] if i > 0 else ""
    text = "".join(s[max(0, i - 3) : i + 1])
    if t == " have" and p in NEGATION:
        return carry, 2.2
    if t in LICENSE:
        return carry, 3.5
    if t in LIMITATION and p in LIMITATION_BEFORE:
        return carry, 3.5
    if (t in ALLAH_TAILS and p in ALLAH_STEMS) or text.lower().endswith("allah") or text.endswith("الله"):
        return carry, 8.0
    if t in {" rights", " Rights"} and p in ALL:
        return carry, -6.5
    if t in {" day", " but", " you", " Saints"} and p in ALL:
        return carry, -2.6
    if t in QUANTIFIER_NEXT and p in QUANTIFIER_BEFORE:
        return carry, 2.5
    if t == "··":
        return carry, -1.0
    return carry, 0.0

programs.sol:
"""Document-opening pulses for title metadata, prose and source code.

The dominant pulse is the colon completing an initial `Title:` header.
At the first token, English definite articles and source-file declarations
also give positive pulses. Markdown headings and block comments give smaller
ones. This approximation leaves ordinary within-document activity at zero.
"""

READS = ()


def opening(token):
    if token == 'Title':
        return -2.424
    if token == 'The':
        return 2.678
    if token.strip().lower() == 'the':
        return 0.7
    if token == 'package':
        return 10.478
    if token in {'import', 'using'}:
        return 2.88
    if token == 'from':
        return 4.068
    if token in {'use', 'module', 'var', 'const', 'int', 'string', 'export'}:
        return 2.35
    if token == "'use":
        return 1.59
    if token == '#include':
        return 0.57
    if token == '#ifndef':
        return 1.52
    if token.startswith('/*'):
        if token.count('*') == 1:
            return 0.5
        if token.startswith('/**\n'):
            return 2.59
        return 1.33 if '\n' in token else 2.5
    if token and set(token) == {'#'} and len(token) >= 2:
        return 1.01 if len(token) == 2 else 1.88
    if token == '<?':
        return 0.37
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        offset, first = 0, token
    else:
        offset, first = carry[1] + 1, carry[2]
    value = opening(token) if offset == 0 else 0.0
    if offset == 1:
        if first == 'Title' and token == ':':
            value = 72.916
        elif first == '<?' and token == 'php':
            value = 2.021
    return (document, offset, first), value

programs.haiku:
"""Layer 1, MLP down-projection, component 4895: a document-start detector.

At the first token of a document the model has no context, so this component's output
depends only on that token. It is large for "The" and for code-opening words, and
hugest for "package". Separately, the ":" that follows a document-initial "Title"
(as in a "Title: ..." header) gives an extreme spike. Everywhere else it is near zero,
which the program predicts as 0.
"""

READS = ()

CODE_OPENERS = {"import", "using", "from", "int", "const", "export", "#include", "#ifndef"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tok = prefix.token_strings[-1]
    if carry is None or doc != carry[0]:
        pos = 0
    else:
        pos = carry[1] + 1
    value = 0.0
    if pos == 0:
        if tok == "package":
            value = 10.5
        elif tok in CODE_OPENERS:
            value = 2.8
        elif tok == "The":
            value = 2.7
    elif pos == 1 and tok == ":" and prefix.token_strings[-2] == "Title":
        value = 73.0
    return (doc, pos), value

programs.sol:
"""Sparse local-text approximation of a heterogeneous component.

The main negative response completes 'as to'; purpose ('so as to'),
addition ('as well as to'), and capitalized 'As to' are weaker.
Positive responses recognize slice/slide word families, including some
split spellings and Japanese/Korean/Russian 'slide' loanwords. Smaller
rules cover 片 (slice/film), console.log, ESLint/TSLint, and 'Show Tags'.
Unrecognized text gets zero. These are selected responses, not a complete
semantic characterization of the component.
"""
import re
from functools import lru_cache
import wordnet
from anyascii import anyascii

READS = ()
AS_COMPLETIONS = {
    'to': -12.1, 'for': -1.0, 'of': -1.0, 'per': -1.3,
    'soon': -1.2, 'long': -0.46, 'compared': -1.7,
    'applied': -3.5, 'if': -1.1, 'though': -1.9, 'regards': -2.6,
}
LETTERS_AT_END = re.compile(r'[^\W\d_]+$')


@lru_cache(maxsize=4096)
def family(word):
    """English morphological family, not an arbitrary token table."""
    if word.startswith('sli'):
        roots = wordnet.base_forms(word)
        if 'slice' in roots:
            return 'slice'
        if 'slide' in roots:
            return 'slide'
    return ''


def spelling_value(word, capital=False):
    root = family(word)
    if root == 'slice':
        if word.endswith('ing'):
            return 5.8
        return 4.4 if word.endswith('s') else 4.0 if word.endswith('d') else 5.3
    if root == 'slide':
        if capital and word.endswith(('e', 's')):
            return 5.3
        if word.endswith('ing'):
            return 1.8
        return 4.3 if word.endswith('s') else 2.3 if word.endswith('d') else 3.0
    return 3.6 if word == 'slic' else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, tail, fragment = (), b'', ''
    else:
        _, history, tail, fragment = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = history[-1].lower() if history else ''
    before = history[-2].lower() if len(history) > 1 else ''
    value = 0.0
    # Local English constructions.
    if fragment.lower() == 'as' and token.startswith(' '):
        value = AS_COMPLETIONS.get(word, 0.0)
        if history[-1] == 'As':
            value = {'to': -8.2, 'for': -3.5, 'of': -0.5}.get(word, value)
        if word == 'to':
            value = {'so': -3.6, 'such': -2.3, 'far': -3.0,
                     'well': -1.5}.get(before, value)
            if (len(history) > 2 and history[-3].lower() == 'so'
                    and before not in {'so', 'such', 'far', 'well'}):
                value = -6.5
        elif word == 'for' and before == 'such':
            value = 0.0
    elif word == 'to':
        value = {'respect': -0.74, 'regard': -1.43}.get(previous, 0.0)
    elif word == 'into':
        if previous == 'insight':
            value = -1.1
        elif 'look' in wordnet.base_forms(previous):
            value = 1.9
    elif word == 'of' and family(previous) == 'slice':
        value = 2.2
    # Slice/slide spelling and inflection, including split words.
    bare = word.lstrip('._')
    lexical = spelling_value(bare, token.lstrip(' ._')[:1].isupper())
    if lexical:
        value = lexical
    if not token[:1].isspace() and fragment.lower() in {'s', 'sl', 'sli'}:
        completion = spelling_value(fragment.lower() + word)
        if completion:
            value = completion if word.endswith('ing') else 1.6 * completion
    if word == '.log' and previous.endswith('console'):
        value = 1.85
    elif word == 'tags' and previous == 'show':
        value = 2.5
    elif word == 'lint' and previous.endswith(('es', 'ts')):
        value = 1.9
    elif token == '片':
        value = 2.2
    # Bytes preserve characters that are divided between tokens.
    tail = (tail + prefix.token_bytes[-1])[-128:]
    match = LETTERS_AT_END.search(tail.decode('utf-8', errors='ignore'))
    new_fragment = match.group().lower() if match else ''
    if new_fragment != fragment and not new_fragment.isascii():
        roman = anyascii(new_fragment).lower()
        # Conventional spellings of the loanword 'slide'.
        if roman.endswith('slayd') and not fragment.endswith('йд'):
            value = 9.3
        elif roman.endswith('seullai') or new_fragment.endswith('スライ'):
            value = 9.2
        elif roman.endswith('seullaideu'):
            value = 6.0
        elif roman.endswith('suraido'):
            value = 8.4
    return (doc, (history + (token.strip(),))[-3:], tail, new_fragment), value

"""Code assignment openings, with negative pulses for quoted fields and escapes.

Spaced equals after a simple variable name is strongest. Bare equals, member
writes, mathematical expressions and long prose left sides are much weaker.
The short text memory supplies line structure and nearby code punctuation;
physical and backslash-encoded newlines are treated alike. Doubled slashes
are positive in nearby TeX formatting, negative as code escapes. Quoted
mapping fields and equals-sign separator banners get negative pulses.
"""
import re

READS = ()
_NAME = re.compile(r'([A-Za-z_$][A-Za-z_0-9$]*)$')
_DECL = re.compile(
    r'\b(?:const|let|var|val|final|static|public|private|protected|int|float|'
    r'double|bool|boolean|char|string|String|auto|unsigned|long|short|mut)\s+'
)
_CODE = re.compile(r';|\b(?:def|function|return|import|class)\b|\n[ \t]{2,}')


def assignment(text, token):
    before = text.replace('\\n', '\n').replace('\\t', '\t')
    line = before.rsplit('\n', 1)[-1]
    match = _NAME.search(before)
    name = match[0] if match else ''
    left = line[:-len(name)] if name else line
    words = len(re.findall(r'\w+', left))
    width = len(left.strip())
    code = bool(_CODE.search(before[-500:]))
    declared = bool(_DECL.search(left))
    spaced = token.startswith(' ')
    # A declaration explicitly establishes assignment, even in a short snippet.
    if spaced and name and declared and words <= 2:
        return 1.5

    if words >= 3:
        if declared and code:
            return 0.6 if width < 33 else 0.33
        if declared:
            return 0.09 if width < 64 else 0.0
        if not name:
            return -0.1
        if left.endswith('.'):
            return -0.3
        return 0.32 if code and spaced else 0.02
    if not spaced:
        if not name:
            return -0.24
        return 0.28 if width == 0 else 0.05
    if not name:
        return -0.4 if width < 4 else (0.19 if code else -0.07)
    if left.endswith('.'):
        return 0.5 if width < 6 else 0.07
    if code:
        return 1.42 if width < 6 else 1.02
    if len(name) <= 2:
        return 0.65 if not left.strip() else 0.13
    return 1.25 if not left.strip() else 0.68


def quoted_field(text):
    end = text.rstrip()
    in_object = text.rfind('{') > max(text.rfind('('), text.rfind('['))
    mapping_nearby = bool(re.search(r'["\']\s*:', text[-150:]))
    if mapping_nearby:
        if end.endswith(','):
            return -1.33 if in_object else -0.68
        key = re.search(r'["\']([^"\']*)["\']:$', end)
        return -0.45 if key and len(key[1]) > 6 else -0.23
    if end.endswith(','):
        blank_line = not text.rsplit('\n', 1)[-1].strip()
        return -0.54 if blank_line else -0.17
    return -0.12 if in_object else 0.027


def predict(text, token):
    s = token.strip()
    if ((s.startswith('=') and not s.startswith(('==', '=>')))
            or s.startswith(':=')) and len(s) < 8:
        value = assignment(text, token)
        return value + 0.3 if ':=' in s else value
    if token in (' "', " '"):
        return quoted_field(text)
    if s == '<-':
        return 1.8 if _NAME.search(text) else 0.9
    if s == '←':
        return 0.8 if _NAME.search(text) else 0.0
    if len(s) == 2 and s[1] == '=' and s[0] in '+-*/%&|^':
        return 0.25 if token.startswith(' ') else 0.08
    if s.endswith('\\\\') and len(s) <= 6:
        latex = re.search(
            r'\\(?:begin|frac|left|right|text|quad|nonumber|hfill)\b',
            text[-500:],
        )
        return 1.3 if latex else -0.8
    if len(s) >= 4 and set(s) == {'='}:
        return -0.4
    return 0.002


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = predict(text, token)
    return (document, (text + token)[-700:]), value

"""Chinese necessity and degree words, including a few split constructions.

Large negative responses mark 'must', 'very', 'quite', 'sufficiently',
and 并且 ('and also'). A weaker lexical response covers related modifiers.
Split 必- ('necessarily') and 超- ('super-/excessively') are recognized
from the immediately preceding token. Most other text is predicted as zero,
except for Vietnamese rất ('very') and a weak positive baseline on
ASCII-alphabetic document-opening tokens. This is a partial lexical
approximation: it leaves many small, scattered vocabulary responses unexplained.
"""
from functools import lru_cache
from opencc import OpenCC
import regex

READS = ()
_SIMPLIFY = OpenCC('t2s')
NECESSITY_AND_DEGREE = {
    '必须': -2.4, '必需': -1.5,
    '非常': -1.15, '相当': -1.8, '十分': -1.45,
}


@lru_cache(maxsize=32768)
def simplified(text):
    return _SIMPLIFY.convert(text)


def response(text, previous, first=False):
    if text in NECESSITY_AND_DEGREE:
        return NECESSITY_AND_DEGREE[text]
    # A merged grammatical prefix or suffix usually weakens the response.
    for word, strength in NECESSITY_AND_DEGREE.items():
        if text in {word + '的', '都' + word}:
            return 0.85 * strength
        if text in {'是' + word, '就' + word, '我们' + word}:
            return 0.7 * strength
        if text in {'也' + word, word + '要'}:
            return 0.5 * strength
    if text == '且' and previous == '并':
        return -1.0
    if text in {'而且', '并且'}:
        return -0.4
    if text in {'的', '地'} and previous in NECESSITY_AND_DEGREE:
        return 0.75 * NECESSITY_AND_DEGREE[previous]
    if text == '得' and previous in {'非', '必', '必须', '一定', '应'}:
        return -1.9
    if text == '常' and previous == '非':
        return -0.85
    if text == '分' and previous == '十':
        return -0.8
    if text == '该' and previous in {'应', '本'}:
        return -1.1
    if previous == '必' and text in {'须', '需', '备', '经', '需要'}:
        return -2.3
    if previous == '必' and regex.fullmatch(r'\p{Script=Han}+', text):
        return -0.4
    if (previous == '超' and regex.fullmatch(r'\p{Script=Han}', text)
            and text not in {'过', '越', '市'}):
        return -0.5
    # Excess quantity and multiplicative expressions.
    if text == '量' and previous == '过':
        return -1.5
    if text == '倍' and previous in {'成', '百'}:
        return -2.0
    if text == '数' and previous == '倍':
        return -2.8
    # Smaller responses to necessity, emphasis, and degree expressions.
    if text in {'须', '得很', '极其', '极为'}:
        return -0.55
    if text in {'不得', '不能', '不允许', '一定要', '务必'}:
        return -0.4
    if text in {'充分', '连续', '格外', '尤为', '特别', '一定'}:
        return -0.3
    if text in {'很', '都很'}:
        return -0.15
    # 'At least' and 'greatly' have the opposite sign.
    if text in {'至少', '大大'}:
        return 0.7
    if text == 'rất':  # Vietnamese 'very'.
        return -1.1
    if first and text.isascii() and text.isalpha():
        return 0.18
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    text = simplified(prefix.token_strings[-1]).strip()
    return (doc, text), response(text, previous, first)

