def predict(s, previous, tail, first):
    word = s.strip()
    if s == ' on' and previous.strip() == 'Posted':
        return 6.6
    if word == 'permalink' and previous.endswith('#'):
        return 3.2
    if word == 'RUN' and previous.strip() == '===':
        return 1.08
    if word == 'PASS' and previous.strip() == '---':
        return .74
    if word == 'finished' and previous.strip() == 'Command':
        return -.83
