        return 3.85
    if word == 'Created' and line in ('//', '/*'):
        return 4.
    if word == 'By' and line == '/*':
        return 8.
    if word == 'by' and (line.startswith('// Created') or
                         re.match(r'/\*\s*(?:Created|Updated):', line)):
        return 3.8
    if previous.strip() == '<!--' and word in ('begin', 'end'):
        return -2.5 if word == 'begin' else -3.5
    if word == '-doc' and previous == '-user' and '<!--' in line:
