"""A checking/ensuring feature, rather than certainty in general.

Checking verbs and 'make sure' clause frames give large pulses;
test names give smaller ones. Only the current and previous token are used.
Chinese checking/light-action expressions and paired middle dots are minor cases.
"""
from functools import lru_cache
from opencc import OpenCC
import wordnet

READS = ()
SIMPLIFY = OpenCC('t2s')
VERBS = {'check': 1.5, 'verify': 4.0, 'confirm': 3.0, 'validate': 3.0,
         'ensure': 2.8, 'review': 0.7, 'assure': 0.9, 'insure': 2.0}
CLAUSE_HEADS = {'check': 8.0, 'verify': 7.0, 'confirm': 4.5,
                'validate': 5.0, 'ensure': 4.0, 'assure': 2.0}
CHINESE = {'确保': 3.4, '确认': 2.2, '检查': 2.1, '验证': 2.8,
           '保证': 1.6, '保障': 1.5, '查看': 2.3, '看看': 1.6,
           '看': 0.7, '一下': 1.4, '看一下': 2.5}


def clean(token):
    return token.strip().lstrip('/._-')


@lru_cache(maxsize=8192)
def verb(word):
    return next((root for root in (word,) + wordnet.base_forms(word)
                 if root in VERBS), None)


@lru_cache(maxsize=8192)
def predict(token, previous):
    raw, prev = clean(token), clean(previous).lower()
    word = raw.lower()
    # Read a checking word even when the tokenizer split it in two.
    joined = clean(previous + token)
    if token and not token[0].isspace() and (
            verb(joined.lower()) or joined.lower() == 'verification'):
        raw, word, prev = joined, joined.lower(), ''
    if word == '··':
        return -1.9
    if word in {'sure', 'certain'}:
        if prev in {'make', 'making', 'makes', 'made'}:
            return 8.6
        return 4.5 if prev == 'be' and word == 'sure' else -0.3
    if word == 'that':
        root = verb(prev)
        if root in CLAUSE_HEADS:
            value = CLAUSE_HEADS[root]
            return value * 0.6 if prev.endswith('ed') else value
        if prev in {'test', 'testing', 'tests'}:
            return 5.0 if clean(previous)[:1].isupper() else 3.0
        return {'sure': 2.0, 'so': 0.75, 'such': 0.75, 'important': 3.0,
                'essential': 3.0, 'require': 2.2, 'requires': 2.2}.get(prev, -0.05)
    if word in {'if', 'whether'}:
        if verb(prev) in CLAUSE_HEADS:
            return 2.2
        return 1.3 if prev == 'see' else (0.5 if word == 'whether' else 0.0)
    if word == 'so':
        if raw != 'so' or not token[:1].isspace():
            return -0.09
        if prev == 'just':
            return 6.0
        if ',' in previous or prev in {'and', 'or', 'if'}:
            return -0.2
        return 0.3 if prev in {'do', 'doing', 'is', 'are', 'was', 'be'} else 0.95
    if prev in {'check', 'verify', 'confirm'} and word in {
            'the', 'it', 'this', 'what', 'which', 'our', 'your', 'my', 'another'}:
        return 0.9
    if joined.lower() == 'testbed':
        return 0.45
    if word == 'test':
        if prev in {'def', 'void', 'func', 'fn'}:
            return 2.3
        if token.startswith('/'):
            return 2.5 if prev == 'tests' else 1.3
        return 1.3 if raw == 'Test' else (0.7 if token.startswith(' ') else 1.05)
    if word in {'tests', 'testing', 'tested'}:
        return 0.5
    if word.startswith('assert'):
        return 4.1 if word == 'assertthat' else 1.4
    if word == 'verification':
        return 4.0 if raw.isupper() else 1.5
    root = verb(word)
    if root:
        value = VERBS[root] * (1.0 if word == root else 0.5)
        if word == root:
            if prev in {'and', 'also', 'now', 'me', 'please'}:
                value *= 1.3
            elif prev in {'can', 'will', 'would', 'not'}:
                value *= 0.5
