    return CHINESE.get(SIMPLIFY.convert(word), 0.0) if not word.isascii() else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), float(predict(token, previous))

"""Approximate three local effects: boilerplate phrase completions, broken
punctuation-heavy fragments, and document beginnings.  Phrase endings receive
fixed pulses, especially in patent, publication, attribution and date formats.
Dangling or mixed exclamations raise current and later punctuation responses.
Negative motifs include initial Title:/12, dot leaders and placeholder emails.
Otherwise predict zero, except for a character-class document-start baseline
and positive declaration-like starts (var/function/const or double underscore).
History is bounded to 192 characters and resets with each document.
"""
import re

READS = ()

# Recognizable attribution, heading and navigation phrase endings.
ATTRIBUTION = {
    'published': ('originally', 2.34),
    'from': ('originally', 2.9),
    'notice': ('copyright', 1.0),
}
HEADINGS = {
    'Updated': ('last', 1.1),
    '»': ('read more', 1.76),
    'OF': ('background', 0.9),
    'DESCRIPTION': ('detailed', 0.84),
    'Work': ('related', 0.62),
    'By': ('written', 0.96),
    'Next': ('prev', 2.45),
    '作者': ('本文', 3.4),  # this article's author
    '来源': ('本文', 1.95),  # this article's source
    '编号': ('案件', 0.75),  # case number
    'Number': ('registration', 0.53),
}
COLON_FIELDS = {
    '摘自': 2.05,  # excerpted from
    'posted in': 1.05,
    'updated': 5.8,
    'author': 3.5,
    'source': 1.75,
    'summary': 1.2,
    'rating': 2.5,
}


def phrase(s, h, position):
    word = s.strip()
    lower = word.lower()
    before = h.lower().rstrip()
    for rules, key in ((ATTRIBUTION, lower), (HEADINGS, word)):
        rule = rules.get(key)
        if rule is not None and before.endswith(rule[0]):
            return rule[1]
    if (len(word) >= 2 and set(word) == {'·'}
            and (position == 0 or before.endswith('·'))):
        return -1.57
    if s == '.lastname' and before.endswith('firstname'):
        return -3.0
    if position == 1 and h == 'Title' and s == ':':
        return -5.755
    if position == 1 and h == '1' and s == '2':
        return -5.33
    if position == 2 and h == '12' and s == '2':
        return -2.1
    if lower == 'relates':
        if re.search(r'\binvention(?: generally)?$', before):
            additional = 'aspect' in before or 'particularly' in before
            return 3.6 if additional else 5.0
        if before.endswith('invention also'):
            return 2.8
        if before.endswith('publication'):
            return 2.3
    if lower == 'to' and re.search(r'\binvention(?: generally)? relates$', before):
        return 0.65 if 'generally' not in before else 1.1
    if lower == 'on':
        if h.rstrip().endswith('Published'):
            return 5.5
        if before.endswith('originally published'):
            return 5.2
        if before.endswith('published'):
            return 1.7
        if h.rstrip().endswith('Written'):
            return 1.26
        if h.rstrip().endswith('Posted'):
            return 1.65
        if before.endswith('later'):
            return 0.83
        if before.endswith('filed'):
            return 0.65
        if before.endswith('found') and 'article' in before:
            return 0.65
        if h.rstrip().endswith('News'):
            return -2.25
        if before.endswith('information'):
            return -0.45
        if before.endswith('details'):
            return -0.9
    if word in ('No', 'Nos'):
        if re.search(r'\b(?:pat\.?|ser\.)$', before):
            return 1.1
        if before.endswith('patent'):
            return 3.0
        if before.endswith('application'):
            return 3.3 if before.endswith('patent application') else 1.9
        if re.search(r'\b(case|contract|file|serial)$', before):
            return 0.9
    if lower == 'date':
        if before.endswith('filing'):
            return 1.03
        if word == 'Date' and h.rstrip().endswith('Publication'):
            return 4.1
        if re.search(r'\b(release|decision|archive)$', before):
            return 0.87 if word == 'Date' else 0.25
        if before.endswith('created'):
            return 0.22
    if s == ' :':
        for label, pulse in COLON_FIELDS.items():
            if before.endswith(label):
                return pulse
        if h.rstrip().endswith('Text'):
            return 1.6
        if h.rstrip().endswith('Time'):
            return 1.9
    if s == ':' and re.search(r'\b(Author|Published|Text)$', h.rstrip()):
        return 0.4
    if lower == 'later':
        if re.search(r'\b(was|were)$', before):
            return 0.3
        if re.search(r'\b(described|explained)$', before):
            return 0.8
    if lower == 'author' and before.endswith('original'):
        return 2.45 if 'copyright' in before else 1.0
    if word == 'Author' and re.search(r'\b(this|the)$', before):
        return 0.65
    if lower == 'under' and h.rstrip().endswith('Licensed'):
        return 0.6
    # Chinese legal abbreviation markers: 'hereinafter called'.
    if word in ('稱', '称') and before.endswith(('以下簡', '以下简')):
        return 5.0
    if word == '以下简称':
        return 3.1
    if position == 0:
        if s in ('var', 'function', 'const'):
            return 1.5
        if s == '__':
            return 0.7
        if s.startswith('<|'):
            return -0.21
        if s.isspace():
            return -0.17
        if word.isdigit():
            return -0.24
        if word.isascii() and word.isalpha():
            if s.startswith(' '):
                return -0.52 if word[0].isupper() else -0.35
            if len(word) == 1:
                return -0.69 if word.isupper() else -0.53
            return -0.58 if word[0].isupper() else -0.33
        return -0.27 if word.isascii() else -0.4
    return 0.0


DANGLING = re.compile(
    r'\b(a|an|the|of|to|for|with|and|or|is|are|be|by|from|in|on|at|as|than)$',
    re.I,
)


def fragment_punctuation(token, history, broken):
    """Repeated broken phrase endings mark fragmentary, punctuation-heavy text."""
    marks = token.strip()
    if not re.fullmatch(r'[.,;:]*[.!]+', marks):
        return broken, None
    dangling = bool(DANGLING.search(history.rstrip()))
    bang = '!' in marks
    mixed = bang and any(c in marks for c in '.,;:')
    if bang and (dangling or mixed):
        broken += 1
    if bang and broken:
        return broken, 0.5
    if len(marks) > 1 and not bang and broken:
        return broken, 0.3
    if marks == '.' and broken >= 2 and dangling:
        return broken, 0.35
    return broken, None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, history, broken = 0, '', 0
    else:
        _, position, history, broken = carry
    token = prefix.token_strings[-1]
    broken, punctuation = fragment_punctuation(token, history, broken)
    value = phrase(token, history, position) if punctuation is None else punctuation
    return (doc, position + 1, (history + token)[-192:], broken), value

