"""Layer-1 MLP neuron 4905 (down_proj), a 'subordinate clause opener' detector.

What it does, in plain terms: this component goes negative on the word that opens an
introductory subordinate or adverbial phrase at the start of a sentence -- the word a
reader sees before the main clause arrives. Typical cases: "Since ...", "While ...",
"Despite ...", "Although ...", "After ...", "Once ...", "As ...", "When ...", and the
Chinese 由于 / 随着. The strongest response is on the concessive/causal openers
(Despite, Since, While, Although); mid-sentence "since", "though" also dip, and the
rest of the text is near zero. It does not track the tokens that follow.

The program predicts that dip: a value on the opener word (and on the 'to' of
"in addition to" / "in order to" / "according to"), zero elsewhere.
"""

READS = ()

# Strongest: concessive and causal openers.
STRONG = {"despite", "since", "while", "although", "though", "once", "after", "based"}
# Weaker: other introductory prepositions/conjunctions that open a fronted phrase.
WEAK = {"as", "when", "with", "by", "during", "because", "according", "given",
        "due", "upon", "before", "unlike", "without", "even", "among", "through"}
# "to" that closes a multi-word connective: in addition to, in order to, according to.
LINKING_NOUNS = {"addition", "order", "according", "contrast"}
CHINESE_OPENERS = {"由于", "随着", "虽然", "尽管", "既然", "鉴于"}

STRONG_VALUE = -0.6
WEAK_VALUE = -0.2
MID_SENTENCE_VALUE = -0.2   # lower-case "since", "though", "although" inside a sentence


def opens_sentence(prefix):
    """True if the newest token starts a sentence, or the text, or a line."""
    if len(prefix.token_strings) == 1:
        return True
    before = prefix.token_strings[-2]
    return before.rstrip() == "" or before.endswith((".", "!", "?", ":", '"', "\n"))


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    word = raw.lower()
    if raw in CHINESE_OPENERS:
        return None, STRONG_VALUE
    if word in STRONG:
        if opens_sentence(prefix):
            return None, STRONG_VALUE
        return None, MID_SENTENCE_VALUE if word in ("since", "though", "although") else 0.0
    if word in WEAK and opens_sentence(prefix):
        return None, WEAK_VALUE
    if word == "to" and len(prefix.token_strings) > 1:
        if prefix.token_strings[-2].strip().lower() in LINKING_NOUNS:
            return None, WEAK_VALUE
    return None, 0.0

programs.sol:
"""A burst on a context-free token, strongest for numbers and whitespace.

At a document's beginning, or while it consists only of repeated copies of
its first token, estimate the burst from the token's readable shape. Once a
different token supplies context, predict the small background value instead.
The large values are mostly digits, indentation, line breaks, and 'a'/'an'.
Nine is a weak exception among digits. The shared gain for other digits is
an approximation; weak lexical responses outside the burst are not modeled.
"""

READS = ()


def initial_value(text):
    if len(text) == 1 and text in '0123456789':
        return 0.22 if text == '9' else 3.5
    if text.isspace():
        if '\n' in text:
            if text.count('\n') > 1:
                return 0.2  # A blank line, rather than a single line break.
            return 2.4 if text == '\n' else 1.0
        if '\t' in text:
            return 3.2 if text.count('\t') == 1 else 1.0
        return 2.8 if len(text) == 1 else 6.4
    if text.strip() == 'a':
        return 2.2 if text.startswith(' ') else 2.8
    if text.strip() == 'an':
        return 1.3
    if text == '.\n':
        return 3.5
    if text in (' (', ' .'):
        return -1.9
    if text == ' =':
        return 1.4
    if text == ' *':
        return 3.0
    if text == ' +':
        return 0.9
    if text == '\\n':
        return 2.5
    if text == '\x00':
        return 3.9
    if text == '<|endoftext|>':
        return 4.5
    if text.startswith('<|'):
        return -0.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        first, uniform = token, True
    else:
        _, first, uniform = carry
        uniform = uniform and token == first
    value = initial_value(prefix.token_strings[-1]) if uniform else -0.002
    return (doc, first, uniform), value

"""Approximate title/organization phrases and a few everyday-life compounds.

The main response is negative on formal geographic and institutional titles,
particularly their linking 'of'. Capitalization distinguishes a named body
from an ordinary noun. A document-initial 'Title:' field is strongly negative;
school/health systems are negative; health-care and everyday-life compounds
are positive.
Unrecognized contexts receive zero. State is just a short text suffix, reset
at each document boundary.
"""
import re

READS = ()

# Strength at 'of' after a capitalized title head.
OF_HEADS = (
    ('city', 11.0),
    ('town borough municipality county district diocese township village province',
     7.0),
    ('republic commonwealth', 6.0),
    ('university college school', 4.3),
    ('department board court office house states', 4.2),
    ('kingdom state order bank church society league party', 3.3),
    ('division ministry academy museum hall bureau', 1.8),
    ('institute cathedral association union council', 1.0),
)
HEAD_STRENGTH = {w: value for words, value in OF_HEADS
                 for w in words.split()}
SYSTEM_HEADS = {'school', 'university', 'education', 'healthcare',
                'hospital', 'retirement', 'library'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    low = word.lower()
    words = re.findall(r'[A-Za-z]+', before.replace('\\n', '\n'))
    m = re.search(r'([A-Za-z]+)\s*$', before.replace('\\n', '\n'))
    previous = m[1] if m else ''
    prev = previous.lower()
    value = 0.0

    continuation = (token and token[0].isalpha() and before
                    and before[-1].isalpha())
    if (low == 'of' and not continuation) or word == '_OF':
        strength = HEAD_STRENGTH.get(prev, 0.0)
        if strength:
            if not previous[0].isupper():
                strength *= 0.33 if strength not in (11.0, 4.3) else 0.42
            value = -strength
        elif previous and previous[0].isupper():
            value = -0.35
        if previous in ('Class', 'Corps'):
            value = -8.0
        elif previous in ('Fellows', 'Legion'):
            value = -5.5
        if word == '_OF':
            value = -1.9
    elif word in ('District', 'Circuit', 'Appeals', 'Department'):
        value = -5.7 if word == 'District' and previous in (
            'States', 'School') else -2.3
    elif low == 'board' and not continuation:
        value = -4.8 if prev in ('county', 'school') else (
            -1.2 if word[0].isupper() else 0.0)
    elif word == 'Veterans':
        value = -1.8
    elif low in ('district', 'department', 'court', 'university', 'college'):
        value = -0.35

    # All-capitals legal headers can split DISTRICT across tokens.
    if word == 'RICT' and previous == 'DIST':
        value = -5.5
    elif word == 'DIST' and any(w in ('STATES', 'APPELLATE', 'COURT')
                                for w in words[-4:]):
        value = -5.0
    elif word == 'COURT' and previous == 'DISTRICT':
        value = -3.5

    if low in ('system', 'systems'):
        if SYSTEM_HEADS.intersection(w.lower() for w in words[-4:]):
            value = -4.8 if word[0].isupper() else -2.7
            if low == 'systems':
                value *= 0.7
    elif low == 'at' and prev == 'college':
        value = -2.5
    elif low == 'care' and prev in ('health', 'hospital'):
        value = 3.5 if previous[0].isupper() or prev == 'hospital' else 2.0
    elif low == 'life' and prev in ('daily', 'everyday', 'family', 'city'):
        value = 3.2

    if prev == 'the':
        if low == 'university':
            value = -0.9
        elif word == 'City':
            value = -2.0
    if word == ':' and before == 'Title':
        value = -11.8

    return (doc, (before + token)[-100:]), value

"""A calibrated prose-opening detector.

Common capitalized English words receive positive pulses after newlines;
questions and mathematical/instructional introductions are especially strong.
Many pulses grow in the first eight document positions. The first token itself has a
separate correction: Han tokens are raised, common English words suppressed.
Other positions stay near zero, with small punctuation corrections. These
rules approximate the line-opening pulses seen in training, not every
token-specific amplitude.
"""
from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()
QUESTIONS = frozenset('what why how who when where which whose whom'.split())
INTRODUCTIONS = frozenset(
    'let use find show write give consider suppose assume given'.split()
)
ARTICLES = frozenset(('a', 'an', 'the'))

@lru_cache(maxsize=32768)
def frequency(word):
    # Integer Zipf-frequency band: larger means more common in English.
    return int(zipf_frequency(word.lower(), 'en')) if word.isalpha() else 0


def opening_value(word, rank, early, bare_newline):
    upper = word[:1].isupper()
    if rank < 6:
        if word.lower() in INTRODUCTIONS:
            return 1.13 if bare_newline else 0.48
        if upper:
            return 0.49 if early else 0.08
        return 0.0
    if early:
        return 1.12
    if not upper:
        return 0.05
    if bare_newline:
        return 0.57 if rank >= 7 else 0.40
    if rank >= 7:
        return 0.33
    return 0.53 if word.lower() in QUESTIONS else 0.18


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        position, line, previous = 0, '', ''
    else:
        _, position, line, previous = carry
    word = s.strip().lstrip('“”\'"([{')
    rank = frequency(word)
    upper = word[:1].isupper()
    after_newline = '\n' in previous or '\\n' in previous
    after_sentence_mark = previous.strip()[-1:] in ('.', '!', '?')
    list_open = bool(line.strip()) and not line.strip(
        ' \t#>*-•0123456789.()[]'
    )

    if after_newline:
        value = opening_value(word, rank, position < 8, not previous.strip())
    elif first:
        if regex.search(r'\p{Script=Han}', word):
            value = 0.79
        elif rank >= 6:
            value = -0.41 if rank >= 7 else -0.20
        elif word.isupper() and rank == 5:
            value = -0.42
        else:
            value = 0.15 if word[:1].islower() else 0.03
    elif after_sentence_mark:
        if list_open:
            value = 0.42 if rank >= 7 else 0.03
        else:
            value = -0.04 if len(word) > 2 else 0.0
    elif upper and not word.isupper() and rank >= 6:
        if rank == 6:
            value = 0.44 if word.lower() in QUESTIONS else 0.04
        else:
            value = 0.25 if word.lower() in ARTICLES else 0.13
    else:
        value = 0.0

    line = (line + s.replace('\\n', '\n')).rsplit('\n', 1)[-1][-100:]
    return (doc, position + 1, line, s), value

"""Approximate responses to whitespace padding and document starts.

A final single-space token after padding is strongly negative, especially in
indentation. Single tabs and nonbreaking spaces following longer runs behave
similarly. Backslash escapes have smaller, separate responses. At a document's
first token, coarse case and length classes supply a baseline instead.
"""

READS = ()


def initial_value(token):
    word = token.strip()
    if token == ' ':
        return 1.812
    if not word:
        return 0.0
    if word.isascii() and word.isdigit():
        return 0.07
    if not (word.isascii() and word.isalpha()):
        return -0.25
    if token.startswith(' '):
        return -0.3 if word.istitle() else -0.17
    if len(word) == 1:
        return 0.19 if word.isupper() else -0.16
    if word[0].isupper():
        return -0.62
    if len(word) <= 3:
        return -0.55
    return -0.2 if len(word) < 8 else 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, blank, position = '', True, 0
    else:
        _, previous, blank, position = carry

    value = 0.0
    if position == 0:
        value = initial_value(token)
    elif token == ' ' and previous and not previous.strip(' '):
        length = len(previous)
        if length == 1:
            value = -0.76 if blank else -0.16
        elif length == 4:
            value = -1.4 if blank else -1.27
        elif length > 4:
            value = -1.0 if blank else -1.14
        else:
            value = -1.23
        if position < 8 and length > 1:
            value -= 1.3 / (1 + position / 2)
    elif token == '\t' and previous.endswith('\t'):
        value = -0.25 if previous == '\t' else -0.52
    elif token == '\u00a0' and len(previous) > 1:
        if not previous.strip('\u00a0'):
            value = -0.75
    elif token.count('\\') >= 2:
        if token.startswith(' '):
            value = 0.53
        elif token == '\\' * 2:
            value = -0.34
        elif token == '\\' * 3:
            value = 0.6 if previous.endswith('}') else -0.12

    if '\n' in token:
        tail = token.rsplit('\n', 1)[-1]
        blank = not tail or tail.isspace()
    elif token and not token.isspace():
        blank = False
    return (doc, token, blank, position + 1), value

programs.haiku:
"""Whitespace inside an indentation run fires this component negative: a bare space
(the padding in front of a right-aligned line number, e.g. "    " then " " then "75") most
strongly, a tab in a run of tabs less so. Words, punctuation and newlines leave it near zero."""

READS = ()


def _pure_space(tok):
    return tok != "" and "\n" not in tok and tok.strip(" \t") == ""


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) < 2:
        return carry, 0.0
    tok, prev = toks[-1], toks[-2]
    if not _pure_space(prev):
        return carry, 0.0
    if tok == " ":
        if len(prev) >= 2:
            return carry, -1.2
        prev2 = toks[-3] if len(toks) >= 3 else "\n"
        if "\n" in prev2 or _pure_space(prev2):
            return carry, -0.9
        return carry, -0.15
    if tok == "\t":
        return carry, -0.4
    return carry, 0.0

programs.sol:
"""A mixture of spelling and vocabulary responses.

The largest response is to arXiv/preprint name fragments. More generally,
word-internal r followed by x, q, h, ch or wh tends to be positive;
some nasal and w continuations are weakly negative. A separate response
covers Marx/socialist terminology and Chinese words for value and ideas.
Finance-related uses of value, repeated middle dots, and small document-start
offsets are also included. These are approximate spelling rules, not a general
topic classifier. Recent bytes are retained and reset at document boundaries.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from opencc import OpenCC

READS = ()
_SIMPLIFY = OpenCC('t2s')


@lru_cache(maxsize=30000)
def roman(text):
    return anyascii(text).lower()


@lru_cache(maxsize=30000)
def simplified(text):
    return _SIMPLIFY.convert(text)


def predict(old, new, start):
    s = simplified(new.strip())
    lower = s.lower()
    match = re.search(r'[A-Za-z]+$', old)
    word = match.group().lower() if match else ''

    # Preprint repositories and the name Marx share conspicuous r-x spelling.
    if word == 'ar' and lower == 'xiv':
        return 14.5
    if word == 'ar' and lower == 'x':
        return 12.8
    if word in ('arx', 'medrx', 'biorx') and lower == 'iv':
        return 11.2
    if word == 'mar' and lower == 'x':
        return 9.4
    if 'marx' in lower:
        return 3.6
    if '马克思' in s or s == '克思主义':
        return 7.7
    if word.endswith('marx') and lower in ('ist', 'ists', 'ism', 'ian'):
        return 5.2

    if lower in ('socialist', 'socialists', 'socialism'):
        return 1.65
    if '社会主义' in s:
        return 3.25
    if s == '主义':
        return 2.3
    if ('价值' in s or s in ('思想', '物质', '事物')
            or (s == '物' and old.endswith('事'))):
        return 2.5
    if lower in ('value', 'values'):
        if word in ('shared', 'shareholder', 'par', 'core', 'social'):
            return 2.2
        if (word in ('market', 'property', 'maturity', 'fair')
                or old.endswith(("'s", '’s'))):
            return 0.77
        return -0.08

    if s == '··' and old.endswith(s):
        return 0.8

    # Transliteration makes the r-continuation rule usable across scripts.
    if new and old and not new[0].isspace():
        if roman(old[-1]) == 'r':
            a = roman(new)
            before = roman(old)
            if new in ('х', 'Х', 'χ', 'Χ'):
                return 4.0
            if a == 'h':
                return 5.0 if before.endswith('gar') else 0.8
            if a in ('x', 'q', 'ql'):
                return 7.0 if before.endswith('ar') else 3.1
            if a == 'wh':
                return 3.7
            if a.startswith('qu'):
                return 0.74
            if a.startswith(('ch', 'rh', 'sh')) or a in ('ach', 'uch', 'uh'):
                return 0.45
            if a.startswith('z'):
                return 0.9 if before.endswith('ar') else 0.25
            if a == 'm' or a.startswith(('ma', 'mo', 'mu')):
                return -0.4
            if a.startswith('w'):
                return -0.17
            if a == 'box' and before.endswith('car'):
                return 1.08  # carboxyl spelling
            if a.startswith(('ct', 'kt')):
                return -0.32
        if lower in ('rh', 'rx'):
            return 1.0

    if start:
        if new[:1].isspace():
            return 0.21
        if not new[:1].isupper():
            return 0.08
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    tail = b'' if start else carry[1]
    old = tail.decode('utf-8', errors='ignore')
    joined = tail + prefix.token_bytes[-1]
    text = joined.decode('utf-8', errors='ignore')
    new = text[len(old):]
    return (doc, joined[-192:]), float(predict(old, new, start))

"""Approximate a mixed lexical/formatting component, not one general concept.

Positive modes: a formatted numeral 1, split indefinite compounds such as
'some thing' and 'somethin', and Thai หน with following vowel pieces.
Negative modes: quantified 'one of', Chinese determiner + 一, and repeated
middle dots. A small regression distinguishes line openings from digits
inside numbers. Document starts get a coarse baseline; otherwise the value
is near zero. Keep only 96 characters of context, resetting per document.
"""
import regex as re

READS = ()


def numeral(before, previous, start):
    # A small regression on formatting and the preceding digit.
    line = bool(re.search(r'(?:\n|\\n)\s*$', before))
    trimmed = re.sub(r'(?:\n|\\n|\s)+$', '', before)
    colon = line and trimmed.endswith((':', '：'))
    han = line and bool(re.search(r'\p{Script=Han}', trimmed[-25:]))
    blank = line and bool(re.search(r'(?:\n\s*){2,}$', before))
    digit = previous[-1:] if previous else ''
    heading = bool(re.search(r'(transcript(?:ion)?|contents)\s*$',
                             trimmed, re.I))
    form = bool(re.search(r'_{3,}\s*$', before))
    indent = line and previous.isspace() and '\n' not in previous
    return (-0.002 + 0.228 * line + 0.185 * colon + 0.327 * han
            + 0.099 * blank + 0.156 * (digit in ('1', '2'))
            - 0.061 * (digit == '0') - 0.215 * indent
            + 0.397 * heading + 0.382 * form + 0.068 * start)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    before, previous = ('', '') if start else carry[1:]
    word, prev = s.strip().lower(), previous.strip().lower()
    value = -0.002
    if len(s) > 1 and set(s) == {'·'}:
        value = -1.375
    elif s == '1':
        value = numeral(before, previous, start)
    elif start:
        if s.startswith('<|') or s.isdigit():
            value = -0.045
        else:
            value = -0.255 if s.strip().isalpha() or s.isspace() else -0.135
    elif word == 'one':
        value = {'some': 0.94, 'no': 0.26, 'every': 0.33,
                 'each': -0.45, 'which': -0.65, 'any': -0.17}.get(prev, -0.03)
    elif word == 'of' and re.search(
            r'\b(each|every|any|which|another)\s+one$', before, re.I):
        value = -1.3
    elif word == 'of' and re.search(r'\bno\s+amount$', before, re.I):
        value = -1.45
    elif word in ('thing', 'things', 'body', 'where'):
        if prev in ('some', 'any', 'every', 'no', 'ever'):
            value = 1.0
    elif word == 'eth' and re.search(r'\bsom$', before, re.I):
        value = 0.85
    elif word == 'in' and re.search(r'\bsometh$', before, re.I):
        value = 1.12
    # Chinese 一 means one: choices/distributives are negative modes.
    elif '一' in s:
        context = before[-1:] + s
        if re.search(r'[哪某]一', context):
            value = -1.75
        elif '任一' in context:
            value = -2.5
        elif re.search(r'[每又]一', context):
            value = -1.1
        elif '同一' in context:
            value = -0.9
        elif re.search(r'[这那上前此]一', context):
            value = -0.55
        elif s == '一' and re.search(r'\n\s*$', before):
            value = 0.4
    # Separate Thai spelling mode and its nearby fragments.
    elif s == 'หน':
        value = 1.3
    elif previous == 'หน':
        value = {'ัง': 1.22, 'ึ': 0.85, 'ี้': 0.72, '้า': 0.4}.get(s, 0.05)
    elif s == 'น':
        value = 1.2 if before.endswith(('ดัง', 'อย่าง')) else 0.3
    elif s == 'ง':
        value = 0.9 if before.endswith(('หนึ่', 'ไ', '่าง', 'รม')) else 0.2
    elif s == 'ไร' and before.endswith('อย่าง'):
        value = 1.1
    return (doc, (before + s)[-96:], s), float(value)

"""A small, local lexical-pattern approximation, not a topic detector.

Positive cues include lowercase sentence openings, ordinal editions/versions,
'so much', and reading/download prompts. Other rules distinguish distributive
'one' from 'no one', code-import syntax, and chat/padding markers. Uncovered
contexts receive zero. Only two previous tokens and document position are kept.
These cues explain only a small part of the component's heterogeneous response.
"""
import re
import inflect

READS = ()
_numbers = inflect.engine()
ORDINAL_WORDS = {
    _numbers.ordinal(_numbers.number_to_words(n)) for n in range(1, 11)
} | {'last'}
ORDINAL_SUFFIXES = {'st', 'nd', 'rd', 'th'}
NUMERIC_ORDINAL = re.compile(r'\d+(?:st|nd|rd|th)')
PRONOUNS = set('i you he she it we they this that these those there'.split())
CONNECTIVES = set(
    'once when while if then now so therefore thus hence however either yet '
    'not only'.split()
)
ABBREVIATIONS = set(
    'al etc inc co mr mrs ms dr st pp p vol no vs ed fig sec ltd'.split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, position = '', '', 0
    else:
        _, previous, before, position = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = previous.strip().lower()
    older = before.strip().lower()
    value = 0.0

    # A lowercased clause after a full stop, excluding common abbreviations.
    if (prev == '.' and token.startswith(' ') and word.isascii()
            and word.isalpha() and token.strip().islower()):
        sentence = (older.isalpha() and len(older) > 2
                    and older not in ABBREVIATIONS)
        value += 0.21 if sentence else 0.01
        if word in PRONOUNS:
            value += 0.23 + (0.15 if sentence else 0.0)
        if word in CONNECTIVES:
            value += 0.26 + (0.28 if sentence else 0.0)
        if word == 'the':
            value += 0.03 + (0.51 if sentence else 0.0)

    # Ordering, quantity, and reference to members of a set.
    ordinal = (prev in ORDINAL_WORDS or NUMERIC_ORDINAL.fullmatch(prev)
               or (prev in ORDINAL_SUFFIXES and older.isdecimal()))
    if ordinal:
        if word in ('edition', 'version', 'iteration'):
            value += 1.16
        elif word == 'one':
            value += 0.40
    if prev == 'so' and word == 'much':
        value += 0.96
    if word == 'one':
        if prev in ('each', 'every'):
            value += 0.68
        elif prev == 'no':
            value -= 0.18
    if word == 'once' and prev in ('was', 'were', 'had', 'has', 'is', 'be', 'been'):
        value += 0.84

    # Reading and download prompts.
    if word in ('download', 'downloads', 'downloading'):
        value += 0.24
    if word in ('read', 'download') and ('\n' in previous or position == 0):
        value += 0.47
    if word in ('epub', 'ebook', 'e-book'):
        value += 0.90

    # Import syntax and explicit formatting markers.
    if token == 'import':
        value -= 0.12
    elif token == ' import':
        value += 0.12
    if prev.endswith('import') and word in ('org', 'com'):
        value += 0.28
    if token and all(c == '·' for c in token):
        value -= 0.42
    if token == '<|im_start|>':
