    word = text.strip()
    spaced = text.startswith(' ')
    if text.startswith('<|'):
        return 0.0
    if not word:
        return 1.39 if text == '\n' else -0.15
    if len(word) == 1 and word.isascii() and word.isdigit():
        return -0.51 if int(word) < 3 else 1.42
    if word.islower():
        if len(word) == 1:
            return 0.52 if spaced else -0.83
        common = zipf_frequency(word, 'en') > 6.3
        if common:
            return 1.0
        return 2.65 if spaced else 1.9
    if word.isupper():
        return -0.8
    if not any(c.isalnum() for c in word):
        if spaced:
            return 2.0
        if len(word) == 1:
            return -0.4
        return 1.0
