"""First token of a document, as the model sees it.

This component is silent except on the first token of a document: position 0 of a packed
row, or the first token after an <|endoftext|> boundary (where the document id changes).
There the model's attention can see only that token, so the component's strength depends
on the token alone, and it is a rough word-class pattern:

- content words with a leading space (" time", " work", " first"): strongest, about +2.8;
- function words with a leading space (" the", " of", " and", " he"): about +1.2;
- lowercase word pieces with no leading space: about +1.5;
- punctuation, digits, code and non-Latin text: about +0.7;
- capitalised words with no leading space: about +0.3;
- single letters and ALL-CAPS tokens: about -0.4;
- special tokens and whitespace: about 0.

Everywhere else it predicts 0. Within each class the actual values vary a lot (a token-level
effect this sketch does not capture), so the explained variance is partial.
"""

READS = ()

# Closed-class English words: articles, prepositions, conjunctions, pronouns, auxiliaries.
FUNCTION_WORDS = frozenset(
    """a an the of and or but nor to in on at by for with from as into over under up out
    about if then than so not no do does did have has had be is are was were been being
    it its this that these those he she they we you i me him her them us my your his their
    our will would can could should may might must shall which who whom whose what when
    where why how all any each some one also just there here""".split()
)


def start_value(token):
    core = token.strip()
    if token.startswith("<|") or not core:
        return 0.0  # special tokens and whitespace
    if not core.isalpha():
        return 0.7  # punctuation, digits, code, non-Latin text
    if len(core) == 1 or core.isupper():
        return -0.4  # single letters and ALL-CAPS words
    if token[0] == " ":
        return 1.2 if core.lower() in FUNCTION_WORDS else 2.8
    if core[0].isupper():
        return 0.3  # a capitalised word with no space before it
    return 1.5  # a lowercase word piece with no space before it


def step(carry, prefix, upstream):
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not new_doc:
        return None, 0.0
    return None, start_value(prefix.token_strings[-1])

"""layers.1.mlp.down_proj:4916 -- a "not only / not just" negation-scope detector.

What it does: this component reads the token that comes right after a negation
("not", "n't", "than", ...) and writes a large positive value when that token is
a limiting word in a construction like

    "not only ..."   "not just ..."   "more than just ..."   "not the only ..."
    "don't have to ..."   "does not need to ..."   "not limited to ..."

and a smaller positive value for articles right after a negation ("not a",
"not the", "more than a"). Right after a negation, a word that says a thing is
impossible, unavailable or unhelpful ("not possible", "not work", "not exist",
"not helpful", "not very", "not so") gets a negative value. Everywhere else it
is about zero.

Predicted values are in the component's own units (its activation).
"""

# Words that open a negation's scope: English not / n't / than (and a few foreign ones).
NEG = {"not", "n't", "'t", "’t", "nicht", "pas", "не", "than"}

# Limiting words: "only", "just", "merely", ... (plus a few in other languages).
ONLY = {"only", "just", "merely", "solely", "simply", "mere", "alone", "exclusively", "purely",
        "solo", "nur", "seulement", "tylko", "alleen", "только", "просто", "不仅", "仅仅", "不僅", "只", "だけ"}

# Articles and intensifiers that follow a negation: "not a", "not the", "not really", "not about".
ARTICLE = {"a", "an", "the", "both", "exactly", "really", "always", "about", "in", "on", "of", "that", "as"}

# "need to" / "have to" / "limited to" (after a negation: "don't have to", "not limited to").
NEED = {"need", "needs", "require", "limited", "confined", "restricted"}
HAVE = {"have", "has", "had"}

# Degree words and "can it be done / does it exist" verbs; negative right after a negation.
DEGREE = {"so", "very", "too", "less", "even"}
POTENTIAL = {"exist", "found", "work", "working", "possible", "helpful", "help", "understand", "allow", "able",
             "provided", "available", "having", "stop", "ideal", "include"}

READS = ()


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    i = len(toks) - 1

    def back(k):
        # The token k places before the current one, within the same document ("" if none).
        j = i - k
        if j < 0 or docs[j] != docs[i]:
            return ""
        return toks[j].strip().lower()

    cur, p1, p2, p3 = back(0), back(1), back(2), back(3)
    if cur in ONLY and (p1 in NEG or p2 in NEG or p3 in NEG):
        return carry, 10.0 if p1 == "than" else 8.0      # "more than just", "not only", "not the only"
    if cur == "necessarily" and p1 in NEG:
        return carry, 3.5                                  # "not necessarily"
    if cur == "to" and (p1 in HAVE or p1 in NEED) and p2 in NEG:
        return carry, 6.0                                  # "don't have to", "not limited to"
    if p1 in NEG and cur in ARTICLE:
        return carry, 2.0                                  # "not a", "not the", "more than a"
    if p1 in NEG and (cur in DEGREE or cur in POTENTIAL):
        return carry, -2.0                                 # "not possible", "not very", "not work"
    return carry, 0.0

