    elif text.startswith('もの'):
        value = 4.9
    elif text == 'こと':
        value = 2.7
    elif text.endswith('こと'):
        value = 2.5
    elif text.startswith('こと'):
        value = 0.55
    elif text == 'ところ':
        value = 4.5
    elif text == '것':
        value = 7.2
    elif '것' in text:
        copula = text.endswith(('이다', '입니다'))
        value = 0.7 if copula else 3.5
    elif '产品' in text or '產品' in text:
        value = 2.25
    elif any(word in text for word in ('商品', '食物', '作品')):
        value = 1.9 if japanese else 0.4
    elif text == '物':
        value = 7.0 if japanese else 0.35
    elif japanese:
        if text in {'事', '者', '品'}:
            value = 2.1
        elif text in {'私', '彼', '彼女'}:
            value = 2.9
        elif text == '自分':
            value = 1.2
        elif text == 'それ':
            value = 4.25
        elif text == 'これ':
            value = 0.7
        elif text in {'誰', '何', 'どれ', '他', '等'}:
            value = 1.5
        elif text.startswith('全') and len(text) <= 2:
            value = -3.8 if len(text) == 1 else -1.0
        elif text == '好':
            value = -4.2
        elif text in {'合', '合格'}:
            value = -3.2
        elif text == '丈夫':
