Common, long English words lean negative; short or unfamiliar fragments lean
positive. Programming declarations, formatting marks and boundary tokens have
separate offsets. The prediction persists through repetitions of the first
token, then becomes zero. Small later activations and word-specific variation
are deliberately not modeled.
"""
import math
from functools import lru_cache
import regex
from wordfreq import get_frequency_dict

READS = ()

# Keywords introducing declarations, types, or dependencies in common languages.
DECLARATIONS = frozenset('''
package import from using namespace class interface struct enum typedef def
function public private protected static extern const let var export module
require include int char float double void bool
'''.split())


@lru_cache(maxsize=4096)
def initial_value(text):
    word = text.strip()
    leading = text[:1].isspace()
    if text == '<|endoftext|>':
        return -12.59
    if text.startswith('<|') and text.endswith('|>'):
        return 0.7
    if not word:
        return -0.90 if text == ' ' else -3.55
    # A byte fragment of a non-ASCII character decodes alone as U+FFFD.
    if '\ufffd' in word:
        return 2.26
    if word.isdigit():
        return -2.04 if word == '0' else -0.75

    if word.lower() in ('and', 'or', 'but', 'nor'):
        return -0.3
    if word.isalpha():
        if regex.fullmatch(r'\p{Script=Latin}+', word):
            frequency = get_frequency_dict('en').get(word.lower(), 0.0)
            zipf = math.log10(frequency) + 9 if frequency else 0.0
            value = (4.46 - 0.76 * zipf - 0.336 * min(len(word), 12)
                     + 0.38 * leading + 0.31 * word.istitle())
            if not leading and word in DECLARATIONS:
                value -= 4.44
            return value
        if regex.search(r'\p{Script=Han}', word):
            return -2.0 if len(word) > 1 else 0.0
        if regex.search(r'\p{Script=Cyrillic}', word):
            return 1.46
        if regex.search(r'[\p{Script=Hiragana}\p{Script=Katakana}]', word):
            return 1.65
        return 2.7

    if word.startswith(('#', '//', '/*', '<!--')):
        return -3.5
    if all(c in '\"“”' for c in word):
        return -5.3 + 2.5 * leading
    if word.startswith(('\\n', '\\t', '\\r')):
        return -4.5
    if all(c in '^~+=*/%&' for c in word):
        return 0.0
    if any(c.isalnum() for c in word):
        return 0.44  # Mixed identifier/word fragments, rather than punctuation.
    return -1.17


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != document:
        value = initial_value(prefix.token_strings[-1])
        carry = (document, token, value, True)
    else:
        doc, first_token, value, initial_run = carry
        initial_run = initial_run and token == first_token
        value = value if initial_run else 0.0
        carry = (doc, first_token, value, initial_run)
    return carry, float(carry[2])

programs.haiku:
"""Layer-1 MLP down_proj, component 4918: a first-token-of-document detector.

Inside a document this component is silent. It speaks only at a document's first token
(the token right after <|endoftext|>, or the first token of a document starting mid-row),
where the model resets attention. There its value depends on what kind of token it is,
judged from the token's characters alone:

  - foreign scripts (CJK, kana, Hangul, Arabic, Thai, Cyrillic): mildly positive;
  - symbols, indentation and code/markup openers (#, //, newlines, tabs, brackets): negative;
  - English function words (the, of, to, in, ...): moderately negative;
  - digits: slightly negative; other words: near a small negative value.

What it does not capture: within each class the real value varies a lot from token to token
(e.g. 'package' -6.3, 'Title' -6.8, 'Kenn' +6.4), with no surface feature that explains it.
A per-token table would explain far more; this rule explains only a small share.
"""
import unicodedata

READS = ()

FUNCTION_WORDS = {"the", "of", "a", "an", "in", "to", "for", "by", "that", "is", "and", "with",
                  "on", "as", "at", "from", "it", "this", "be", "or", "are", "was", "which", "not"}
FOREIGN = ("CJK", "HIRAGANA", "KATAKANA", "HANGUL", "ARABIC", "THAI", "CYRILLIC")
VALUE = {"foreign": 0.4, "symbol": -1.2, "function": -1.75, "digit": -1.0, "word": -0.2}


def kind(s):
    """The class of a token string standing alone."""
    body = s.strip()
    if any(unicodedata.name(c, "").split(" ")[0] in FOREIGN for c in body):
        return "foreign"
    if body == "" or s.startswith(("\n", "\t")) or not body[0].isalnum():
        return "symbol"
    if body.lower() in FUNCTION_WORDS:
        return "function"
    if body[0].isdigit():
        return "digit"
    return "word"


def step(carry, prefix, upstream):
    t = prefix.position
    starts_doc = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    if not starts_doc:
        return carry, 0.0
    return carry, VALUE[kind(prefix.token_strings[t])]

