                "million", "almost", "couple", "several"}
# marks right before a digit that make it the value of a quantity
SYMBOLS = {".", "$", "≈", "=", "-", "+", "–", "(", "\xa0"}
# words right before a number that make it the value of a quantity
CUE_WORDS = {"of", "about", "is", "at", "by", "with", "for", "to", "than", "from",
             "and", "or", "that", "as", "be", "are", "was", "over", "per"}


def is_cjk(tok):
    return any("一" <= c <= "鿿" for c in tok)


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    if cur not in DIGIT_WEIGHT:
        return None, SCALE * (0.4 if cur.strip().lower() in NUMBER_WORDS else 0.0)
    prev = toks[-2] if len(toks) > 1 else ""
    if prev in DIGIT_WEIGHT:
        gain = 1.0                  # a later digit of a number
    elif prev in SYMBOLS:
        gain = 2.5                  # "2.5", "$8", "= 3"
    elif prev.strip() == "" and len(toks) > 2 and toks[-3].strip().lower() in CUE_WORDS:
        gain = 2.5                  # "about 8", "rate of 85"
    elif prev.strip().lower() in CUE_WORDS:
        gain = 2.5
    else:
        gain = 0.8
    if any(is_cjk(t) for t in toks[-30:]):
        gain *= 1.5                 # CJK text runs hotter
    return None, SCALE * DIGIT_WEIGHT[cur] * gain

programs.sol:
"""Estimate boundaries inside written words and identifiers.

Digits appended to letter runs, and TitleCase pieces joined to other
TitleCase pieces, get positive values. Ordinary word continuations are
weaker, with English word frequency separating words from suffix fragments.
Document starts are negative; chat-message endings are positive (less so
for tool messages). A document-initial 'Title:' header has a strong negative
colon response. These are approximate rules, not a lexical token table.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=32768)
def frequency(word):
    if word.isascii() and word.isalpha():
        return zipf_frequency(word, 'en')
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, False)
    _, p, word, pieces, previous_was_first = carry
    first = not p
    if s[:1].isalnum() and (p[-1:].isalnum() or p.endswith('_')):
        word += s
        pieces += 1
    else:
        word, pieces = s.lstrip(), 1
    word = re.split(r'[^\w]', word)[-1]
    a, b = s.lstrip(), p.lstrip()
    f = frequency(a)
    value = 0.0

    if first:
        value = -0.195 - 0.28 * (f < 5.9)
        value -= 0.20 * (a.isalnum() and len(a) <= 4)
        value += 0.20 * (f >= 7)
    elif s == '<|im_end|>':
        value = 0.52 if p in ('</tool_call>', '</tool_response>') else 1.06
    elif s[:1].isdigit() and p[-1:].isalpha():
        value = 0.42
        if len(p) <= 3:
            value = 0.17 if frequency(b) else 0.01
            if len(word) <= 2:
                value = 0.07
    elif s[:1].isalpha() and p[-1:].isalpha():
        if a.istitle():
            if b.istitle():
                value = 0.135 if b.isupper() else 0.46
                if len(word) > 11 and pieces > 2:
                    value = -0.08
            else:
                value = 0.04 if pieces <= 2 else 0.22
                if len(word) > 11:
                    value = 0.0 if pieces <= 2 else 0.08
        elif f >= 3:
            if frequency(word) == 0:
                value = 0.17 if b.isupper() else 0.065
            else:
                value = -0.03 if len(word) <= 3 else 0.03
    elif s[:1].isalpha() and p[-1:].isdigit():
        value = 0.025 if pieces <= 2 else 0.09
    elif s.startswith('_') or p.endswith('_'):
        value = -0.04

    if s == ':' and p == 'Title' and previous_was_first:
        value = -7.9
    return (doc, s, word, pieces, first), float(value)

"""Approximate capital emphasis, name placeholders, and conversation boundaries.

All-capital fragments receive a score based on length, ASCII versus other
scripts, vowels, and English word familiarity. Recent capitals inhibit it.
NAME placeholders and completed all-caps test outcomes have stronger responses.
Chat endings are positive, with smaller values after tool markup; reasoning
and tool delimiters have their own signed responses. Repeated interpunct
leaders and a row-initial end-of-text sentinel receive negative values.
These coarse text rules explain only part of the component's variation.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=8192)
def familiarity(word):
    return zipf_frequency(word.lower(), 'en')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, word = 0.0, ''
    else:
        recent, word = carry[1:]
    text = prefix.token_strings[-1]
    upper = sum(ch.isupper() for ch in text)
    lower = sum(ch.islower() for ch in text)
    capitals = upper >= 2 and lower == 0
    # Keep only the current uninterrupted capitalized word, including fragments.
    for ch in text:
        word = (word + ch)[-32:] if ch.isupper() else ''

    value = 0.0
    if capitals:
        value = 0.35 - 0.075 * recent
        if text.isascii():
            value -= 0.17
        if upper == 2:
            value -= 0.15
        elif upper == 3 or upper >= 6:
            value -= 0.06
        if text[:1].isspace():
            value -= 0.06
        if any(ch in 'AEIOUY' for ch in text):
            value += 0.08
        frequency = familiarity(word)
        value += 0.04 * (frequency >= 4) + 0.06 * (frequency >= 5)
    elif upper == 1 and lower == 0:
        value = -0.01

    label = text.strip().lstrip('._')
    if label.lower() == 'name':
        value = (0.65 if text[:1].isspace() else 0.42) if capitals else 0.10
    elif word == 'PASSED':
        value = 0.90
    elif word in {'FAIL', 'FAILED', 'SUCCESS'}:
        value = 0.48
    elif word == 'NOT':
        value = 0.60 - 0.15 * min(recent, 4)

    if text == '<|im_end|>':
        previous = prefix.token_strings[-2] if prefix.position else ''
        value = 1.0
        if previous == '</tool_call>':
            value = 0.045
        elif previous == '</tool_response>':
            value = 0.25
    elif text == '</think>':
        value = 0.85
    elif text == '<think>':
        value = -0.21
    elif text == '<tool_call>':
        value = 0.25
    elif text == '</tool_response>':
        value = -0.32
    elif text in ('</tool_call>', '<tool_response>'):
        value = -0.065
    elif len(text) >= 2 and set(text) == {'·'}:
        value = -1.51
    elif text == '<|endoftext|>' and prefix.position == 0:
        value = -2.13

    recent = 0.8 * recent + float(capitals) + 0.15 * (upper == 1 and lower == 0)
    return (doc, recent, word), value

"""Sparse responses to typographic signs and isolated medical logograms.

Section/paragraph signs and trademarks give positive pulses, especially
section signs following a C.F.R. citation. A second response is to isolated
Chinese/Japanese symptom, disease, diagnosis and certification characters,
and the related Korean syllable 증. UTF-8 fragments are joined before
recognizing a character; some unfinished letterlike
symbols and Han prefixes already produce a pulse. The latter rules concern
UTF-8 token boundaries, not the meaning of the surrounding passage.
Unrecognized tokens have a small negative bias at document starts,
and are otherwise zero.
"""
import codecs
from opencc import OpenCC

READS = ()
SIMPLIFY = OpenCC('t2s')
ILLNESS_PREFIX = '症'.encode('utf8')[:2]
LETTERLIKE_PREFIX = '™'.encode('utf8')[:2]
# These two-byte Han prefixes cover sun, wood and ritual-sign glyphs.
SUN_PREFIX = '昀'.encode('utf8')[:2]
WOOD_PREFIX = '楼'.encode('utf8')[:2]
RITUAL_PREFIX = '神'.encode('utf8')[:2]


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    initial = carry is None or carry[0] != document
    if initial:
        pending, context = b'', ''
    else:
        _, pending, context = carry
    raw = prefix.token_bytes[-1]
    combined = pending + raw
    text, used = codecs.utf_8_decode(combined, 'replace', False)
    pending = combined[used:]
    token = text.strip()
    spaced = raw.startswith(b' ')
    value = 0.0

    if token and set(token) == {'§'}:
        if len(token) > 1:
            value = 1.9 if spaced else 0.7
        else:
            value = 0.95 if spaced else 0.49
        if 'C.F.R.' in context[-35:]:
            value = 2.4
    elif token == '¶':
        value = 1.8 if spaced else 0.94
    elif token == '™':
        value = 2.7
    elif token == '®':
        value = 0.45
    elif token == '℃':
        value = 2.7 if len(raw) == 1 else 1.2
    elif token == '№':
        value = 0.7
    elif token == '°':
        value = 0.3 if spaced else 0.11
    elif token == '⎯':
        value = -0.48
    # 증 can denote symptoms or certification in Sino-Korean compounds.
    elif token == '증':
        value = 1.4
    elif token and any(ord(ch) > 127 for ch in token):
        word = SIMPLIFY.convert(token)
        # 症: symptom; 疾: illness/rapid; 诊: diagnosis; 证: evidence.
        if word == '症':
            value = 8.0 if len(raw) == 1 else 4.4
        elif word == '疾':
            modifier = SIMPLIFY.convert(context[-1:])
            # Distinguish serious/chronic illness from the 'rapid' sense.
            value = (3.3 if modifier == '重' else
                     5.0 if modifier == '旧' else 0.7)
        elif word == '诊':
            value = 2.5 if context.endswith(('确', '確')) else 0.9
        elif word == '确诊':
            value = 1.2
        elif word == '证':
            value = 0.5
        elif word == '病':
            value = 0.3
        elif word == '症状':
            value = 0.7
        elif word == '疾病':
            value = 0.5

    if pending == ILLNESS_PREFIX:
        value = 6.0 if len(raw) == 1 else 1.7
    elif len(raw) == 1 and pending == WOOD_PREFIX:
        value = 3.2
    elif len(raw) == 1 and pending == RITUAL_PREFIX:
        value = 2.7
    elif len(raw) == 1 and pending == SUN_PREFIX:
        value = 1.2
    elif pending == LETTERLIKE_PREFIX:
        value = 0.7

    if initial and value == 0.0:
        value = -0.14
    context = (context + text)[-80:]
    return (document, pending, context), value

"""A word-fragment boundary approximation.

A short lowercase chunk after several letters gets a positive response,
stronger if the word-so-far is absent from nine languages' frequency tables.
Fragments already recognized as words, uppercase chunks and ordinary word
starts respond less. Document starts and repetitions of long tokens that do
not continue a letter run have negative responses. Only spelling, case,
length and word familiarity are used, not individual token-specific offsets.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ("en", "de", "fr", "es", "it", "pl", "tr", "ro", "ru")


@lru_cache(maxsize=16384)
def familiar(word):
    return any(zipf_frequency(word, lang) > 0 for lang in LANGUAGES)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, word = ('', '') if first else carry[1:]
    size = len(token.strip())
    byte_size = len(token.strip().encode('utf-8'))
    continuing = token[:1].isalpha() and previous[-1:].isalpha()
    value = -0.004

    if first:
        if token[:1].isalpha():
            value = -0.60 if token.islower() else -0.35
        else:
            value = -0.33 if byte_size > 3 else -0.14
    elif continuing:
        stem_length = len(word)
        if stem_length <= 2:
            value = -0.08 if byte_size <= 2 else -0.03
        elif not token.islower():
            value = 0.02 if stem_length == 3 else (
                0.10 if previous.isupper() else 0.0)
        else:
            known_word = familiar((word + token).lower())
            if stem_length == 3:
                value = -0.01 if known_word else 0.07
            elif stem_length == 4:
                value = 0.04 if known_word else 0.17
            elif known_word:
                value = 0.14 if byte_size <= 4 else 0.02
            else:
                value = 0.32 if size <= 4 else 0.09
    elif token == previous and byte_size > 3:
        value = -0.64

    # Save just the trailing letter run, not the whole text prefix.
    tail = re.search(r'[^\W\d_]+$', token)
    if tail:
        letters = tail.group()
        word = (word + letters)[-100:] if letters == token else letters
    else:
        word = ''
    return (doc, token, word), float(value)

"""Approximate an English past-tense / past-participle signal.

WordNet identifies inflections. Personal subjects and 'have' strengthen the
negative response; 'be', 'to', adjective readings and capitals weaken it.
Split words receive a smaller response. The first token gets a positive
correction because it lacks preceding context. This is a grammatical
approximation, not a table of individual words' activation strengths.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
BE = {'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being'}
HAVE = {'have', 'has', 'had'}
SUBJECTS = {'i', 'we', 'you', 'he', 'she', 'it', 'they'}

@lru_cache(maxsize=65536)
def verb_type(word):
    if not word.isascii() or not word.isalpha():
        return 0, False
    if word in {'was', 'were', 'had', 'did'}:
        return 3, False
    if word in BE | HAVE | {'does', 'do'} or word.endswith(('s', 'ing')):
        return 0, False
    bases = wordnet.base_forms(word, 'verb')
    if not any(base != word for base in bases):
        return 0, False
    return (1 if word.endswith('ed') else 2,
            'adjective' in wordnet.parts_of_speech(word))

def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0)
    _, previous, recent, position = carry
    match = re.search(r'([A-Za-z]+)$', previous + token)
    word = match.group(1) if match else ''
    lower = word.lower()
    kind, adjective = verb_type(lower)
    whole = lower == token.strip().lower()
    context = recent[:-len(previous)] if previous and not whole else recent
    words = re.findall(r'[a-z]+', context.lower())[-4:]
    auxiliaries = [w for w in words if w in BE | HAVE]

    value = 0.002
    if kind == 3:
        value -= {'was': 0.038, 'were': 0.038,
                  'had': 0.330, 'did': 0.760}[lower]
    elif kind:
        response = -0.636 if kind == 1 else -0.578
        if auxiliaries:
            response += 0.529 if auxiliaries[-1] in BE else -0.457
        if set(words[-3:]) & SUBJECTS:
            response -= 0.244
        if words and words[-1] in SUBJECTS:
            response -= 0.810
        if adjective:
            response += 0.175
        if whole and word[0].isupper():
            response += 0.171
        if words and words[-1] == 'to':
            response += 0.467
        value += response if whole else 0.6 * response - 0.065
        if position == 0:
            value += 1.065
    elif re.fullmatch(r'\s*[A-Za-z]{3,}ed', token):
        value -= 0.132
    if token.strip() == 'ed':
        value -= 0.164
    return (doc, word[-80:], (recent + token)[-100:], position + 1), value
